const e="mirai_2028",r="1.0.0",a="Future History MIRAI 2028（試作3D：FH01 単一光子SPAD/QIS ＋ FH02 3層垂直RGB）",t="Future History MIRAI 2028 — Prototype 3D Watchmaker Structures (FH01 & FH02)",o=32,i=JSON.parse('[{"id":"mirai-fh01-baffle-frame","diagramType":"mirai_fh01_baffle_frame","order":1,"miraiSubView":1,"swatchColor":"#334155","groupKey":"fh01_optics","assembledPos":[0,6.15,0],"explodeOffset":[0,38,0],"edgeOpacity":0.26,"title":"FH01-01. CNCナイフエッジ迷光遮光バッフル枠","subtitle":"CNC Machined 3-Step Knife-Edge Stray-Light Aperture Baffle Frame","category":"FH01 SPAD/QIS / 最前面光学遮光機構","plainAnalogy":"暗闇のわずかな1粒の光を逃さず、横からの不要な反射光だけを3段の黒いつばで完全にシャットアウトする精密マスク枠です。","summary":"36×24 mmフルサイズSPAD/QIS受光面の最前面を規定する5軸CNC削り出し遮光ベゼル。3段のナイフエッジ遮光リブと植毛級低反射コートにより、0.0005 lux極暗所撮像時の迷光ゴーストを物理的に遮断します。","opticsAndPhysics":["SPADは光子1個をアバランシェ増倍するため、パッケージ縁からのわずかな斜入射反射光（迷光）でも偽カウントとして暗部階調を損ないます。","内径41.2 mm→38.0 mmへ階段状に絞った3層ナイフエッジリブが、臨界角外の斜入射光を多重吸収し、反射率0.3%未満の暗室開口を形成します。","四隅のSUS304位置決めカラーにより、レンズマウント基準面に対して±8 μm以内の光軸センタリングを保証します。"],"formula":{"expression":"R_stray = R_wall^3 < 10^-5 (3-bounce knife-edge trap)","description":"3段ナイフエッジ内壁の多重反射減衰により、開口部外周からの迷光混入を10万分の1以下へ抑制します。"},"nextGenInnovation":"極低照度ISO 400万相当運用に耐える、光学黒（OB）画素完全遮光＋迷光ゼロ開口ベゼル構造。","specs":[{"label":"外形寸法","value":"58.4 × 46.4 × 1.42 mm"},{"label":"有効開口","value":"38.0 × 26.0 mm（3段ナイフエッジ）"},{"label":"表面処理","value":"硬質黒色アルマイト＋超低反射フロック層"},{"label":"位置決め精度","value":"±8 μm（SUSカラー4点基準）"}],"references":["Canon MS-510 1-inch 3.2MP SPAD Low-Light Camera Optical Aperture Requirements (NAB 2026)","ISO 9358 Standard for Veiling Glare & Stray-Light Baffle Attenuation in Imaging Optics"],"mirai":{"fhId":"FH01","volume":1,"badge":"量産民主化","eta":"2027 Q4〜2028 Q3","score":86,"axes":[18,15,18,19,16],"scoreRationale":"光子ショットノイズ限界へ迫る物理突破（18点）と暗闇の撮影体験革命（19点）が際立つ。一方、極暗所でのビニング必須性、SPADのDCR・高輝度消費電力、フルサイズ3D積層歩留まりの厳しさを織り込み量産民主化15点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"読み出しノイズ","current2026":"1.0〜2.7 e-rms","future2028":"0 e-rms（SPADデジタル計数）／0.15〜0.21 e-rms（QIS）"},{"metric":"単一露出DR","current2026":"84〜96 dB（14〜16段）","future2028":"125〜140 dB（20〜23段・サブフレーム外挿HDR）"},{"metric":"極暗所カラー撮影","current2026":"ISO 51,200〜102,400でノイズ床に埋没","future2028":"画素ビニング＋時間積算併用で0.0005 lux・ISO 400万相当カラー"},{"metric":"画素ピッチ＆高画素化","current2026":"3.7〜6 μm（24〜66MP）","future2028":"SPAD：4.9〜6.6 μm（20〜36MP）／QIS：1〜2 μmジョット統合"}],"sourceUrls":[{"label":"Newsshooter（2026年4月15日、Canon 1型3.2MP SPADカメラ「MS-510」発表：0.0006 lux極暗所カラー対応）","url":"https://www.newsshooter.com/2026/04/15/canon-announces-1-inch-spad-sensor-ms-510-extreme-low-light-multi-purpose-camera/"},{"label":"Chida et al. / Canon（MDPI *Sensors* 2025年10月、5 μmピッチ1MP 3D-BSIカラーSPAD：25℃ DCR 3.9 cps・消費電力1.053 W）","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12608571/"},{"label":"Sony J. Ogi et al. / IEEE ISSCC 2021（ResearchGate：250fps・124 dB DR 3D積層画素並列光子カウンタSPAD・サブフレーム外挿HDR）","url":"https://www.researchgate.net/publication/350172286_75_A_250fps_124dB_Dynamic-Range_SPAD_Image_Sensor_Stacked_with_Pixel-Parallel_Photon_Counter_Employing_Sub-Frame_Extrapolating_Architecture_for_Motion_Artifact_Suppression"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (1)","url":"https://opg.optica.org/abstract.cfm?uri=optica-4-12-1474"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (2)","url":"https://www.researchgate.net/publication/350865712_A_019e-_rms_Read_Noise_167Mpixel_Stacked_Quanta_Image_Sensor_With_11_mm-Pitch_Backside_Illuminated_Pixels"},{"label":"Mordor Intelligence（2026年10月、産業・車載SPAD市場と3D積層量産投資動向）","url":"https://www.mordorintelligence.com/industry-reports/spad-imaging-sensors-for-industrial-vision-market"}],"beginnerTitle":"たった1粒の光を守る「3段つば付き」迷光ガード枠","beginnerSummary":"単一光子センサーは「光の粒1個」にも反応するほど超高感度なため、横から漏れたわずかな反射光すらノイズになります。この黒いアルミ枠は3段の階段状フチで余計な光を吸い込み、レンズの正面からの光だけを真っすぐ届けます。","beginnerPoints":["真っ黒な3段のナイフエッジ（刃先状の段差）が、斜めから飛び込む邪魔な反射光を完全にキャッチして消します。","四隅の金属リングでカメラ本体とミクロン単位でピタッと位置合わせし、周辺のピントずれ（片ボケ）を防ぎます。","前面のエメラルド・ラインは2028年世代「FH01」単一光子モジュールの識別マーキングです。"],"beginnerCaution":"SPADは超高感度なぶん、レンズ内のゴーストやセンサー前面の反射がそのまま写り込むため、従来機以上に徹底した遮光設計が必須です。","glossaryIds":["001","010","012"]}},{"id":"mirai-fh01-ar-coverglass","diagramType":"mirai_fh01_ar_coverglass","order":2,"miraiSubView":1,"swatchColor":"#38bdf8","groupKey":"fh01_optics","assembledPos":[0,4.95,0],"explodeOffset":[0,31.5,0],"edgeOpacity":0.16,"title":"FH01-02. 超低反射マルチAR封止カバーガラス＆コバール枠","subtitle":"Ultra-Low-Reflectance Multi-AR Borosilicate Cover Glass & Kovar Frit Seal","category":"FH01 SPAD/QIS / 気密封止光学窓","plainAnalogy":"ガラス表面の反射を0.15%以下に抑え、1粒の光子も跳ね返さずに奥のセンサーへ通す特注の気密ガラス窓です。","summary":"400〜700 nm帯の透過率99.6%超を達成する両面多層ARコート光学ガラスと、低熱膨張コバール合金フリット封止リングの複合窓。パッケージ内を乾燥不活性ガスで気密保護しつつ、SPAD二次発光反射ゴーストを最小化します。","opticsAndPhysics":["通常のカバーガラス（片面反射4%）では暗闇で貴重な光子の約8%を失うため、9層以上の誘電体干渉ARコートで片面反射0.15%未満を実現します。","コバール合金（CTE ≈ 5.1 ppm/K）とアルミナセラミックの熱膨張係数を整合させ、−20℃〜+70℃の温度サイクルでもガラス歪み・複屈折を防ぎます。","SPADアバランシェ発火時に生じる微弱な二次光子（Secondary Photon Emission）がガラス裏面で反射して隣接画素へ戻るクロストークもAR膜が抑制します。"],"formula":{"expression":"T_window = (1 - R_AR)^2 > 99.6% (λ = 420–680 nm)","description":"両面超広帯域ARコーティングにより、単一光子レベルの入射光損失を極限まで低減します。"},"nextGenInnovation":"SPAD特有の二次発光バックリフレクションまで織り込んだ超広角入射対応AR封止窓。","specs":[{"label":"ガラス寸法","value":"50.8 × 38.8 × 0.78 mm"},{"label":"可視透過率","value":"≥ 99.6%（両面多層AR）"},{"label":"封止方式","value":"コバール合金フリット気密接合"},{"label":"平面度","value":"λ / 4 以下（@632.8 nm）"}],"references":["Chida et al. / Canon, MDPI Sensors 2025 (PMC12608571) — 3D-BSI Color SPAD Optical Crosstalk Suppression","ASTM F15 Kovar Glass-to-Metal Hermetic Sealing Alloy Standard"],"mirai":{"fhId":"FH01","volume":1,"badge":"量産民主化","eta":"2027 Q4〜2028 Q3","score":86,"axes":[18,15,18,19,16],"scoreRationale":"光子ショットノイズ限界へ迫る物理突破（18点）と暗闇の撮影体験革命（19点）が際立つ。一方、極暗所でのビニング必須性、SPADのDCR・高輝度消費電力、フルサイズ3D積層歩留まりの厳しさを織り込み量産民主化15点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"読み出しノイズ","current2026":"1.0〜2.7 e-rms","future2028":"0 e-rms（SPADデジタル計数）／0.15〜0.21 e-rms（QIS）"},{"metric":"単一露出DR","current2026":"84〜96 dB（14〜16段）","future2028":"125〜140 dB（20〜23段・サブフレーム外挿HDR）"},{"metric":"極暗所カラー撮影","current2026":"ISO 51,200〜102,400でノイズ床に埋没","future2028":"画素ビニング＋時間積算併用で0.0005 lux・ISO 400万相当カラー"},{"metric":"画素ピッチ＆高画素化","current2026":"3.7〜6 μm（24〜66MP）","future2028":"SPAD：4.9〜6.6 μm（20〜36MP）／QIS：1〜2 μmジョット統合"}],"sourceUrls":[{"label":"Newsshooter（2026年4月15日、Canon 1型3.2MP SPADカメラ「MS-510」発表：0.0006 lux極暗所カラー対応）","url":"https://www.newsshooter.com/2026/04/15/canon-announces-1-inch-spad-sensor-ms-510-extreme-low-light-multi-purpose-camera/"},{"label":"Chida et al. / Canon（MDPI *Sensors* 2025年10月、5 μmピッチ1MP 3D-BSIカラーSPAD：25℃ DCR 3.9 cps・消費電力1.053 W）","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12608571/"},{"label":"Sony J. Ogi et al. / IEEE ISSCC 2021（ResearchGate：250fps・124 dB DR 3D積層画素並列光子カウンタSPAD・サブフレーム外挿HDR）","url":"https://www.researchgate.net/publication/350172286_75_A_250fps_124dB_Dynamic-Range_SPAD_Image_Sensor_Stacked_with_Pixel-Parallel_Photon_Counter_Employing_Sub-Frame_Extrapolating_Architecture_for_Motion_Artifact_Suppression"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (1)","url":"https://opg.optica.org/abstract.cfm?uri=optica-4-12-1474"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (2)","url":"https://www.researchgate.net/publication/350865712_A_019e-_rms_Read_Noise_167Mpixel_Stacked_Quanta_Image_Sensor_With_11_mm-Pitch_Backside_Illuminated_Pixels"},{"label":"Mordor Intelligence（2026年10月、産業・車載SPAD市場と3D積層量産投資動向）","url":"https://www.mordorintelligence.com/industry-reports/spad-imaging-sensors-for-industrial-vision-market"}],"beginnerTitle":"光の粒を99.6%通す「超透明・気密ガラス窓」","beginnerSummary":"普通の窓ガラスは光の約8%を跳ね返してしまいますが、暗闇で星明かりを撮るFH01にとって8%の損失は致命的です。極薄の反射防止膜を何層も重ね、ほぼすべての光の粒をスッと通しながらセンサーをホコリや湿気から守ります。","beginnerPoints":["両面の特殊反射防止（AR）コートにより、400〜700 nmの可視光を99.6%以上透過させます。","外周のコバール金属フレームがセラミック容器とピタッと密着し、温度が変わってもガラスが歪みません。","SPAD素子が光に反応したときに出るごく弱い二次反射光も、ガラス裏面で跳ね返らないよう抑えます。"],"beginnerCaution":"F1.2などの大口径レンズでは端の光がかなり斜めに入るため、正面だけでなく斜め角度でも反射が増えない高度なAR設計が必要です。","glossaryIds":["001","010","101"]}},{"id":"mirai-fh01-ocl-microlens-array","diagramType":"mirai_fh01_ocl_microlens_array","order":3,"miraiSubView":1,"swatchColor":"#7dd3fc","groupKey":"fh01_optics","assembledPos":[0,2.86,0],"explodeOffset":[0,25,0],"edgeOpacity":0.18,"title":"FH01-03. ギャップレス・オンチップマイクロレンズ配列（OCL）","subtitle":"Gapless High-Fill-Factor On-Chip Microlens Array (SPAD PDP Boost)","category":"FH01 SPAD/QIS / 画素直上集光光学系","plainAnalogy":"1つひとつの画素の真上に隙間なく並べた極小の虫めがね群で、光の粒をSPAD中心の感知エリアへムダなく集めます。","summary":"SPAD画素周辺に不可欠な高耐圧ガードリング領域（非受光部）による開口率低下を劇的に補う、高開口・ギャップレスOCLマイクロレンズアレイ。光子検出確率（PDP）をシリコン単体限界へ引き上げます。","opticsAndPhysics":["SPAD画素は20〜28 Vの高電界を維持するガードリングが外周を囲むため、マイクロレンズ無しでは実効開口率（Fill Factor）が40〜55%へ低下します。","ギャップレス半球状OCLが画素ピッチ全体に入射した光子を中央のアバランシェ増倍領域へ急峻に集光し、実効開口率を85%超・ピークPDPを70〜80%級へ引き上げます。","像高（画面中央〜四隅）に応じた瞳補正シフト量（CRAシフト）をウェーハ面内で連続設計し、フルサイズ周辺部のシェーディングを防ぎます。"],"formula":{"expression":"PDP_eff = FF_optical · QE_Si · P_avalanche(V_ex)","description":"OCLによる光学的開口率（FF_optical）向上と過剰バイアス電圧V_ex下の雪崩確率の積が実効光子検出確率を決めます。"},"nextGenInnovation":"ASI光学シミュレーションで最適化された非球面ギャップレスOCLにより、4.9〜6.6 μm小ピッチSPADでも高PDPを達成。","specs":[{"label":"レンズ構造","value":"ギャップレス高屈折率樹脂/石英OCL"},{"label":"実効集光開口率","value":"≥ 85%（ガードリング領域を補償）"},{"label":"対応画素ピッチ","value":"4.9〜6.6 μm（SPAD）/ 1〜2 μm（QIS）"},{"label":"周辺瞳補正","value":"像高連続CRAシフト最適化"}],"references":["Chida et al. / Canon, MDPI Sensors 2025 (PMC12608571) — High-PDP 5 μm 3D-BSI SPAD Microlens Optics","Sony J. Ogi et al., IEEE ISSCC 2021 — Back-Illuminated SPAD Optical Fill-Factor Enhancement"],"mirai":{"fhId":"FH01","volume":1,"badge":"量産民主化","eta":"2027 Q4〜2028 Q3","score":86,"axes":[18,15,18,19,16],"scoreRationale":"光子ショットノイズ限界へ迫る物理突破（18点）と暗闇の撮影体験革命（19点）が際立つ。一方、極暗所でのビニング必須性、SPADのDCR・高輝度消費電力、フルサイズ3D積層歩留まりの厳しさを織り込み量産民主化15点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"読み出しノイズ","current2026":"1.0〜2.7 e-rms","future2028":"0 e-rms（SPADデジタル計数）／0.15〜0.21 e-rms（QIS）"},{"metric":"単一露出DR","current2026":"84〜96 dB（14〜16段）","future2028":"125〜140 dB（20〜23段・サブフレーム外挿HDR）"},{"metric":"極暗所カラー撮影","current2026":"ISO 51,200〜102,400でノイズ床に埋没","future2028":"画素ビニング＋時間積算併用で0.0005 lux・ISO 400万相当カラー"},{"metric":"画素ピッチ＆高画素化","current2026":"3.7〜6 μm（24〜66MP）","future2028":"SPAD：4.9〜6.6 μm（20〜36MP）／QIS：1〜2 μmジョット統合"}],"sourceUrls":[{"label":"Newsshooter（2026年4月15日、Canon 1型3.2MP SPADカメラ「MS-510」発表：0.0006 lux極暗所カラー対応）","url":"https://www.newsshooter.com/2026/04/15/canon-announces-1-inch-spad-sensor-ms-510-extreme-low-light-multi-purpose-camera/"},{"label":"Chida et al. / Canon（MDPI *Sensors* 2025年10月、5 μmピッチ1MP 3D-BSIカラーSPAD：25℃ DCR 3.9 cps・消費電力1.053 W）","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12608571/"},{"label":"Sony J. Ogi et al. / IEEE ISSCC 2021（ResearchGate：250fps・124 dB DR 3D積層画素並列光子カウンタSPAD・サブフレーム外挿HDR）","url":"https://www.researchgate.net/publication/350172286_75_A_250fps_124dB_Dynamic-Range_SPAD_Image_Sensor_Stacked_with_Pixel-Parallel_Photon_Counter_Employing_Sub-Frame_Extrapolating_Architecture_for_Motion_Artifact_Suppression"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (1)","url":"https://opg.optica.org/abstract.cfm?uri=optica-4-12-1474"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (2)","url":"https://www.researchgate.net/publication/350865712_A_019e-_rms_Read_Noise_167Mpixel_Stacked_Quanta_Image_Sensor_With_11_mm-Pitch_Backside_Illuminated_Pixels"},{"label":"Mordor Intelligence（2026年10月、産業・車載SPAD市場と3D積層量産投資動向）","url":"https://www.mordorintelligence.com/industry-reports/spad-imaging-sensors-for-industrial-vision-market"}],"beginnerTitle":"光の粒を中心へ集める「無数の極小虫めがね（OCL）」","beginnerSummary":"SPADセンサーは高い電圧に耐えるため、1マスごとのフチに「安全壁（ガードリング）」が必要で、そのままでは光を受けられる面積が狭くなります。そこで1マスごとに隙間なく並べた極小の虫めがねで光をど真ん中へ集め、1粒も無駄にしません。","beginnerPoints":["3Dモデル上でガラスの粒が整然と並ぶように、実際のセンサーには2,000万〜3,600万個の超微小レンズが敷き詰められます。","レンズ同士のスキマを極限までゼロ（ギャップレス）に近づけ、暗闇で飛んでくる貴重な光子を逃しません。","画面の端ではレンズの位置をわずかにズラして、斜めから来る光も正面と同じく綺麗に受け止めます。"],"beginnerCaution":"マイクロレンズの曲率や焦点がわずか数十ナノメートルずれるだけで集光効率が落ちるため、300mmウェーハ全面での均一加工が量産の要です。","glossaryIds":["001","002","010","103"]}},{"id":"mirai-fh01-spad-top-die","diagramType":"mirai_fh01_spad_top_die","order":4,"miraiSubView":1,"swatchColor":"#0284c7","groupKey":"fh01_silicon","assembledPos":[0,2.38,0],"explodeOffset":[0,19,0],"edgeOpacity":0.22,"title":"FH01-04. 第1積層ウェーハ：36×24mm 3D-BSI SPAD/QIS受光ダイ","subtitle":"Top Tier Wafer: 36×24mm Full-Frame 3D-BSI Single-Photon SPAD / QIS Active Die","category":"FH01 SPAD/QIS / 単一光子光電変換シリコン層","plainAnalogy":"光の粒たった1個が当たった瞬間に「1！」と反応する、読み出しノイズ完全ゼロのフルサイズ単一光子受光チップです。","summary":"36×24 mmフルサイズ全面に20〜36MP級SPAD（または超低容量ポンプゲートQISジョット群）を高密度集積した第1層裏面照射（BSI）シリコンダイ。光子1個の入射をガイガーモード・アバランシェ増倍（または0.15〜0.21 e-rms超低ノイズ読出し）で離散検出します。","opticsAndPhysics":["SPADはp-n接合に降伏電圧以上の逆バイアス（20〜28 V）を印加し、光子1個が生んだ電子を10⁵〜10⁶倍へ雪崩増倍することで、読み出しノイズ0 e-rmsの純デジタル光子計数を実現します。","0.0005 lux・F1.4・1/30秒では6 μm画素1個に平均約0.013光子しか届かないため、極暗所ISO 400万相当モードでは4×4〜9×9ビニング（実効2〜4MP級）と時間積算を自動併用しても読み出しノイズが一切増えず、ポアソン・ショットノイズ限界（SNR=√N）の純粋な画質を引き出します。","明所〜中照度では20〜36MPフル解像度を維持しつつ、光子到着間隔外挿（Sub-Frame Extrapolation）により125〜140 dB（20〜23段）の単一露出HDRを達成します。"],"formula":{"expression":"SNR_photon = N_sig / sqrt(N_sig + DCR · t_exp)  (Read Noise = 0 e-rms)","description":"読み出しノイズ項が完全消失し、信号対雑音比は入射光子数N_sigと暗計数率DCRのみで決定されます。"},"nextGenInnovation":"1枚のフルサイズ受光ダイで「暗闇ビニングISO 400万カラー」と「昼間20〜36MP＋23段HDR」を無縫合に両立。","specs":[{"label":"受光面サイズ","value":"36.0 × 24.0 mm（35mmフルサイズ）"},{"label":"読み出しノイズ","value":"0 e-rms（SPAD）/ 0.15–0.21 e-rms（QIS）"},{"label":"単一露出DR","value":"125〜140 dB（20〜23段・外挿HDR）"},{"label":"暗計数率（DCR）","value":"目標 ≤ 2–4 cps @ 25℃（5 μm画素基準）"}],"references":["Newsshooter (2026-04-15) — Canon 1-inch 3.2MP SPAD Camera MS-510 (0.0006 lux)","Chida et al. / Canon, MDPI Sensors 2025 (PMC12608571) — 5 μm 1MP 3D-BSI Color SPAD (DCR 3.9 cps)","J. Ma & E. Fossum / Gigajot, Optica 2017 — 0.19–0.21 e-rms Stacked QIS"],"mirai":{"fhId":"FH01","volume":1,"badge":"量産民主化","eta":"2027 Q4〜2028 Q3","score":86,"axes":[18,15,18,19,16],"scoreRationale":"光子ショットノイズ限界へ迫る物理突破（18点）と暗闇の撮影体験革命（19点）が際立つ。一方、極暗所でのビニング必須性、SPADのDCR・高輝度消費電力、フルサイズ3D積層歩留まりの厳しさを織り込み量産民主化15点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"読み出しノイズ","current2026":"1.0〜2.7 e-rms","future2028":"0 e-rms（SPADデジタル計数）／0.15〜0.21 e-rms（QIS）"},{"metric":"単一露出DR","current2026":"84〜96 dB（14〜16段）","future2028":"125〜140 dB（20〜23段・サブフレーム外挿HDR）"},{"metric":"極暗所カラー撮影","current2026":"ISO 51,200〜102,400でノイズ床に埋没","future2028":"画素ビニング＋時間積算併用で0.0005 lux・ISO 400万相当カラー"},{"metric":"画素ピッチ＆高画素化","current2026":"3.7〜6 μm（24〜66MP）","future2028":"SPAD：4.9〜6.6 μm（20〜36MP）／QIS：1〜2 μmジョット統合"}],"sourceUrls":[{"label":"Newsshooter（2026年4月15日、Canon 1型3.2MP SPADカメラ「MS-510」発表：0.0006 lux極暗所カラー対応）","url":"https://www.newsshooter.com/2026/04/15/canon-announces-1-inch-spad-sensor-ms-510-extreme-low-light-multi-purpose-camera/"},{"label":"Chida et al. / Canon（MDPI *Sensors* 2025年10月、5 μmピッチ1MP 3D-BSIカラーSPAD：25℃ DCR 3.9 cps・消費電力1.053 W）","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12608571/"},{"label":"Sony J. Ogi et al. / IEEE ISSCC 2021（ResearchGate：250fps・124 dB DR 3D積層画素並列光子カウンタSPAD・サブフレーム外挿HDR）","url":"https://www.researchgate.net/publication/350172286_75_A_250fps_124dB_Dynamic-Range_SPAD_Image_Sensor_Stacked_with_Pixel-Parallel_Photon_Counter_Employing_Sub-Frame_Extrapolating_Architecture_for_Motion_Artifact_Suppression"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (1)","url":"https://opg.optica.org/abstract.cfm?uri=optica-4-12-1474"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (2)","url":"https://www.researchgate.net/publication/350865712_A_019e-_rms_Read_Noise_167Mpixel_Stacked_Quanta_Image_Sensor_With_11_mm-Pitch_Backside_Illuminated_Pixels"},{"label":"Mordor Intelligence（2026年10月、産業・車載SPAD市場と3D積層量産投資動向）","url":"https://www.mordorintelligence.com/industry-reports/spad-imaging-sensors-for-industrial-vision-market"}],"beginnerTitle":"光の粒を1つずつ数える「単一光子フルサイズ受光チップ」","beginnerSummary":"今のカメラは光をバケツに電気として溜めて電圧を測るため、どうしても読み出し雑音（ノイズ）が混ざります。FH01の主役であるこのチップは、光の粒1個が当たった瞬間に「1！」とデジタルで数えるため読み出しノイズがゼロになります。","beginnerPoints":["読み出しノイズがゼロなので、暗闇で隣の画素同士を束ねても（画素ビニング）雑音が増えず、ISO 400万相当のカラー映像が撮れます。","昼間は画素を束ねず2,000万〜3,600万画素の高精細撮影へ自動切替し、太陽と影を同時に写す23段の超広明暗幅（HDR）もこなします。","チップ表面の細かい格子は、1つひとつの画素が光の粒を受け止める超微細なアバランシェ受光セルです。"],"beginnerCaution":"真っ暗闇（0.0005 lux）では飛んでくる光の粒そのものが極端に少ないため、物理法則上、高解像度を維持したまま無ノイズにするのは不可能で、自動ビニングや時間積算との併用が必須になります。","glossaryIds":["001","002","010","012","103"]}},{"id":"mirai-fh01-dti-guard-grid","diagramType":"mirai_fh01_dti_guard_grid","order":5,"miraiSubView":1,"swatchColor":"#64748b","groupKey":"fh01_silicon","assembledPos":[0,1.68,0],"explodeOffset":[0,13.5,0],"edgeOpacity":0.2,"title":"FH01-05. メタル充填F-DTI光学遮蔽＆高耐圧ガードリング格子","subtitle":"Metal-Filled Full-Depth Trench Isolation (F-DTI) & HV Guard-Ring Matrix","category":"FH01 SPAD/QIS / 画素間光学・電界分離構造","plainAnalogy":"1つひとつの画素を頑丈な金属の壁で完全に仕切り、隣の画素への光漏れや高電圧の飛び火を防ぐハチの巣ガード壁です。","summary":"シリコン受光層を貫通するメタル充填フルディープトレンチ分離（F-DTI）とASI最適化高耐圧ガードリングの3D格子構造。SPAD雪崩発火時に発生する二次光子（Optical Crosstalk）と28 V高電界リークを物理遮断します。","opticsAndPhysics":["SPADが1回アバランシェ増倍すると約10⁻⁵個の近赤外二次光子が放出され、隣接画素へ漏れると連鎖誤カウント（光学クロストーク）を引き起こします。","シリコン層を完全貫通するSiO₂＋タングステン/アルミ充填F-DTI壁が二次光子を全反射・遮蔽し、光学クロストークを0.1%未満へ抑え込みます。","2027〜2028年のASI-TCAD自動電界設計により、エッジブレークダウンを防ぎつつガードリング幅を極限まで縮小し、高画素化と低DCRを両立します。"],"formula":{"expression":"P_xtalk < 10^-3  &  E_edge < E_crit (3 × 10^5 V/cm)","description":"メタルF-DTIによる光学クロストーク0.1%未満抑制と、ガードリング端部の電界集中回避を同時に満たします。"},"nextGenInnovation":"ASI-TCAD逆設計による極細ガードリング×完全貫通メタルF-DTIの同時最適化。","specs":[{"label":"トレンチ構造","value":"SiO₂ライナー＋タングステン充填F-DTI"},{"label":"光学クロストーク","value":"< 0.1%（二次発光遮断）"},{"label":"耐圧設計","value":"≥ 30 V（エッジ降伏抑止）"},{"label":"設計手法","value":"ASI-TCAD 3D電界・光学連成最適化"}],"references":["Chida et al. / Canon, MDPI Sensors 2025 (PMC12608571) — F-DTI Crosstalk Suppression in 5 μm Color SPAD","Sony Semiconductor Solutions — Metal-Filled Full-Depth Trench Isolation for Stacked SPAD"],"mirai":{"fhId":"FH01","volume":1,"badge":"量産民主化","eta":"2027 Q4〜2028 Q3","score":86,"axes":[18,15,18,19,16],"scoreRationale":"光子ショットノイズ限界へ迫る物理突破（18点）と暗闇の撮影体験革命（19点）が際立つ。一方、極暗所でのビニング必須性、SPADのDCR・高輝度消費電力、フルサイズ3D積層歩留まりの厳しさを織り込み量産民主化15点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"読み出しノイズ","current2026":"1.0〜2.7 e-rms","future2028":"0 e-rms（SPADデジタル計数）／0.15〜0.21 e-rms（QIS）"},{"metric":"単一露出DR","current2026":"84〜96 dB（14〜16段）","future2028":"125〜140 dB（20〜23段・サブフレーム外挿HDR）"},{"metric":"極暗所カラー撮影","current2026":"ISO 51,200〜102,400でノイズ床に埋没","future2028":"画素ビニング＋時間積算併用で0.0005 lux・ISO 400万相当カラー"},{"metric":"画素ピッチ＆高画素化","current2026":"3.7〜6 μm（24〜66MP）","future2028":"SPAD：4.9〜6.6 μm（20〜36MP）／QIS：1〜2 μmジョット統合"}],"sourceUrls":[{"label":"Newsshooter（2026年4月15日、Canon 1型3.2MP SPADカメラ「MS-510」発表：0.0006 lux極暗所カラー対応）","url":"https://www.newsshooter.com/2026/04/15/canon-announces-1-inch-spad-sensor-ms-510-extreme-low-light-multi-purpose-camera/"},{"label":"Chida et al. / Canon（MDPI *Sensors* 2025年10月、5 μmピッチ1MP 3D-BSIカラーSPAD：25℃ DCR 3.9 cps・消費電力1.053 W）","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12608571/"},{"label":"Sony J. Ogi et al. / IEEE ISSCC 2021（ResearchGate：250fps・124 dB DR 3D積層画素並列光子カウンタSPAD・サブフレーム外挿HDR）","url":"https://www.researchgate.net/publication/350172286_75_A_250fps_124dB_Dynamic-Range_SPAD_Image_Sensor_Stacked_with_Pixel-Parallel_Photon_Counter_Employing_Sub-Frame_Extrapolating_Architecture_for_Motion_Artifact_Suppression"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (1)","url":"https://opg.optica.org/abstract.cfm?uri=optica-4-12-1474"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (2)","url":"https://www.researchgate.net/publication/350865712_A_019e-_rms_Read_Noise_167Mpixel_Stacked_Quanta_Image_Sensor_With_11_mm-Pitch_Backside_Illuminated_Pixels"},{"label":"Mordor Intelligence（2026年10月、産業・車載SPAD市場と3D積層量産投資動向）","url":"https://www.mordorintelligence.com/industry-reports/spad-imaging-sensors-for-industrial-vision-market"}],"beginnerTitle":"隣の画素への「光漏れ・電圧漏れ」を防ぐ金属の仕切り壁","beginnerSummary":"SPADは光の粒が当たると内部で小さな電気の火花（アバランシェ）を起こします。このときわずかな二次光が横へ飛ぶと隣の画素が勘違いしてカウントしてしまうため、金属入りの深い壁（F-DTI）で1マスずつ厳重に隔離します。","beginnerPoints":["タングステン金属と酸化膜の細い壁が、隣の画素への光漏れ（光学クロストーク）を0.1%以下まで遮断します。","20〜28 Vという高い電圧が隅で暴発しないよう、AI（TCAD）が電気の流れ方を最適化して壁の幅を極細に仕上げます。","仕切り壁を細くできた分だけ光を受け止める面積が広がり、フルサイズ2,000万〜3,600万画素の高精細化が可能になります。"],"beginnerCaution":"壁を細くしすぎると絶縁破壊や暗計数（DCR）の悪化を招くため、超精密エッチングと側壁欠陥の無害化（パッシベーション）が不可欠です。","glossaryIds":["001","008","103"]}},{"id":"mirai-fh01-cucu-microbumps","diagramType":"mirai_fh01_cucu_microbumps","order":6,"miraiSubView":1,"swatchColor":"#d97706","groupKey":"fh01_silicon","assembledPos":[0,0.85,0],"explodeOffset":[0,8.2,0],"edgeOpacity":0.18,"title":"FH01-06. Cu-Cuハイブリッド接合 3D銅マイクロピラー層","subtitle":"300mm Wafer-to-Wafer Cu-Cu Hybrid Bonding Direct Pixel Interconnect Layer","category":"FH01 SPAD/QIS / 画素並列3D垂直配線層","plainAnalogy":"上の受光チップと下の計算チップを、数千万本の超極細「銅の直結パイプ」で1画素ずつ真下へつなぐ3D接合層です。","summary":"上層SPAD/QIS受光ダイと下層クエンチ・TDCロジックダイを、SiCN絶縁膜の分子間接合とサブミクロン〜数μmピッチの銅直接接合（Cu-Cu Hybrid Bonding）で1画素ごとに完全垂直接続する3D積層インターコネクト層。","opticsAndPhysics":["従来のマイクロバンプ（はんだ球）では寄生容量とピッチ限界（>20 μm）のため画素並列SPAD接続が不可能でした。Cu-Cuハイブリッド接合によりピッチ1〜5 μm級・超低寄生容量（<1 fF）の画素直結が実現します。","寄生容量を極小化することで、1回のSPADアバランシェ発火あたりに充放電される電荷量 Q = C_node · V_ex が激減し、明所での消費電力急増と二次発光を大幅に低減します。","300mmウェーハ一括接合とCMPディッシング制御（ナノメートル精度平坦化）の成熟が、フルサイズSPAD/QISの量産民主化を支える核心製造技術です。"],"formula":{"expression":"E_fire = 1/2 · (C_spad + C_CuCu) · V_ex^2","description":"Cu-Cu直結による配線寄生容量C_CuCuの極小化が、1光子カウントあたりの消費エネルギーと発熱を直接削減します。"},"nextGenInnovation":"数千万接点のCu-Cuハイブリッド接合により、全画素が独立して真下のデジタルカウンタへピコ秒直結。","specs":[{"label":"接合ピッチ","value":"1.5〜5.0 μm（画素1対1直結）"},{"label":"絶縁接合層","value":"プラズマ活性化 SiCN 誘電体膜"},{"label":"ノード寄生容量","value":"< 1.0 fF / 接点"},{"label":"量産プロセス","value":"300mm W2W（Wafer-to-Wafer）ハイブリッド接合"}],"references":["Sony J. Ogi et al., IEEE ISSCC 2021 — Cu-Cu Connected Pixel-Parallel SPAD Photon Counter","Mordor Intelligence (2026-10) — 300mm 3D-Stacked SPAD Foundry Hybrid Bonding Ecosystem"],"mirai":{"fhId":"FH01","volume":1,"badge":"量産民主化","eta":"2027 Q4〜2028 Q3","score":86,"axes":[18,15,18,19,16],"scoreRationale":"光子ショットノイズ限界へ迫る物理突破（18点）と暗闇の撮影体験革命（19点）が際立つ。一方、極暗所でのビニング必須性、SPADのDCR・高輝度消費電力、フルサイズ3D積層歩留まりの厳しさを織り込み量産民主化15点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"読み出しノイズ","current2026":"1.0〜2.7 e-rms","future2028":"0 e-rms（SPADデジタル計数）／0.15〜0.21 e-rms（QIS）"},{"metric":"単一露出DR","current2026":"84〜96 dB（14〜16段）","future2028":"125〜140 dB（20〜23段・サブフレーム外挿HDR）"},{"metric":"極暗所カラー撮影","current2026":"ISO 51,200〜102,400でノイズ床に埋没","future2028":"画素ビニング＋時間積算併用で0.0005 lux・ISO 400万相当カラー"},{"metric":"画素ピッチ＆高画素化","current2026":"3.7〜6 μm（24〜66MP）","future2028":"SPAD：4.9〜6.6 μm（20〜36MP）／QIS：1〜2 μmジョット統合"}],"sourceUrls":[{"label":"Newsshooter（2026年4月15日、Canon 1型3.2MP SPADカメラ「MS-510」発表：0.0006 lux極暗所カラー対応）","url":"https://www.newsshooter.com/2026/04/15/canon-announces-1-inch-spad-sensor-ms-510-extreme-low-light-multi-purpose-camera/"},{"label":"Chida et al. / Canon（MDPI *Sensors* 2025年10月、5 μmピッチ1MP 3D-BSIカラーSPAD：25℃ DCR 3.9 cps・消費電力1.053 W）","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12608571/"},{"label":"Sony J. Ogi et al. / IEEE ISSCC 2021（ResearchGate：250fps・124 dB DR 3D積層画素並列光子カウンタSPAD・サブフレーム外挿HDR）","url":"https://www.researchgate.net/publication/350172286_75_A_250fps_124dB_Dynamic-Range_SPAD_Image_Sensor_Stacked_with_Pixel-Parallel_Photon_Counter_Employing_Sub-Frame_Extrapolating_Architecture_for_Motion_Artifact_Suppression"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (1)","url":"https://opg.optica.org/abstract.cfm?uri=optica-4-12-1474"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (2)","url":"https://www.researchgate.net/publication/350865712_A_019e-_rms_Read_Noise_167Mpixel_Stacked_Quanta_Image_Sensor_With_11_mm-Pitch_Backside_Illuminated_Pixels"},{"label":"Mordor Intelligence（2026年10月、産業・車載SPAD市場と3D積層量産投資動向）","url":"https://www.mordorintelligence.com/industry-reports/spad-imaging-sensors-for-industrial-vision-market"}],"beginnerTitle":"上下のチップを真下へ直結する「数千万本の銅ピラー」","beginnerSummary":"光を受け止める上の層と、光の数を数える下の頭脳チップを、1マスずつ極細の銅の柱（Cu-Cuハイブリッド接合）で真っすぐ直結します。距離が短く電気のムダが極限まで減るため、高速カウントと省エネを両立できます。","beginnerPoints":["昔のはんだ付けでは大きすぎて不可能だった「全画素1対1の真下直結」を、300mmウェーハ丸ごとの精密銅接合で実現します。","接続が超極細・超短距離になることで電気容量が減り、明るい昼間に何百万回カウントしても発熱と電池消費を抑えられます。","3Dモデルを分解すると、上下のシリコンチップの間にびっしり並ぶ銅色の柱群がくっきり見えます。"],"beginnerCaution":"36×24 mmの大面積フルサイズで数千万本すべての銅の柱を1ミクロンのズレもなく接合するのは非常に難しく、ファブの歩留まり改善が価格低下のカギです。","glossaryIds":["001","101","106"]}},{"id":"mirai-fh01-quench-tdc-wafer","diagramType":"mirai_fh01_quench_tdc_wafer","order":7,"miraiSubView":1,"swatchColor":"#1d4ed8","groupKey":"fh01_silicon","assembledPos":[0,0.05,0],"explodeOffset":[0,3,0],"edgeOpacity":0.22,"title":"FH01-07. 第2積層ウェーハ：画素並列クエンチ＆TDCカウンタ層","subtitle":"Middle Tier Logic Wafer: Pixel-Parallel Active Quench, Picosecond TDC & 14-Bit Counter","category":"FH01 SPAD/QIS / 画素並列デジタル計数ロジック層","plainAnalogy":"光の粒が当たるたびに瞬時にリセットをかけ、1秒間に何百万回も正確に「1、2、3…」と数え上げる超高速デジタル数取器チップです。","summary":"先端FinFET/FD-SOIプロセスで製造され、各SPAD画素の真下にアクティブ・クエンチ回路、リチャージ制御、14-bitデジタル光子カウンタ、およびサブフレーム到着時刻外挿用TDC（時間デジタル変換器）を並列実装した第2層ロジックウェーハ。","opticsAndPhysics":["SPADは光子検出直後に雪崩電流を強制停止（クエンチ）し再充電するまでの数ナノ秒間が「デッドタイム」となります。アクティブ・クエンチ回路がデッドタイムを5 ns以下へ短縮します。","高輝度シーンではカウンタが満杯になるまでの「飽和到達時間（Time-to-Saturation）」をTDC/サブフレーム外挿で計測することで、物理的なビット上限を超えた125〜140 dB（20〜23段）の単一露出HDRを動体破綻なく生成します。","極暗所では隣接4×4〜9×9画素のデジタルカウント値をノイズゼロのまま加算するオンチップ・デジタルビニング回路が動作します。"],"formula":{"expression":"N_est = N_sat · (T_frame / T_sat)  →  DR = 20 · log10(N_max / 1) ≈ 125–140 dB","description":"サブフレーム飽和到達時刻T_satから真の入射光子レートを逆算する外挿HDRにより20〜23段のダイナミックレンジを実現します。"},"nextGenInnovation":"明所では「外挿HDR＋適応クエンチ間引き省電力」、暗所では「無ノイズ・デジタルビニング」をリアルタイム自動切替。","specs":[{"label":"デッドタイム","value":"≤ 5 ns（アクティブ・クエンチ＋リチャージ）"},{"label":"画素並列カウンタ","value":"12〜14 bit リプル/LFSRカウンタ＋TDC"},{"label":"HDR拡張方式","value":"サブフレーム光子到着間隔外挿（20〜23段）"},{"label":"消費電力制御","value":"高輝度時フレーム適応クエンチ間引き"}],"references":["Sony J. Ogi et al., IEEE ISSCC 2021 — 250fps 124dB SPAD with Sub-Frame Extrapolating Architecture","Chida et al. / Canon, MDPI Sensors 2025 (PMC12608571) — 1.053 W Low-Power 3D-BSI Color SPAD Logic"],"mirai":{"fhId":"FH01","volume":1,"badge":"量産民主化","eta":"2027 Q4〜2028 Q3","score":86,"axes":[18,15,18,19,16],"scoreRationale":"光子ショットノイズ限界へ迫る物理突破（18点）と暗闇の撮影体験革命（19点）が際立つ。一方、極暗所でのビニング必須性、SPADのDCR・高輝度消費電力、フルサイズ3D積層歩留まりの厳しさを織り込み量産民主化15点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"読み出しノイズ","current2026":"1.0〜2.7 e-rms","future2028":"0 e-rms（SPADデジタル計数）／0.15〜0.21 e-rms（QIS）"},{"metric":"単一露出DR","current2026":"84〜96 dB（14〜16段）","future2028":"125〜140 dB（20〜23段・サブフレーム外挿HDR）"},{"metric":"極暗所カラー撮影","current2026":"ISO 51,200〜102,400でノイズ床に埋没","future2028":"画素ビニング＋時間積算併用で0.0005 lux・ISO 400万相当カラー"},{"metric":"画素ピッチ＆高画素化","current2026":"3.7〜6 μm（24〜66MP）","future2028":"SPAD：4.9〜6.6 μm（20〜36MP）／QIS：1〜2 μmジョット統合"}],"sourceUrls":[{"label":"Newsshooter（2026年4月15日、Canon 1型3.2MP SPADカメラ「MS-510」発表：0.0006 lux極暗所カラー対応）","url":"https://www.newsshooter.com/2026/04/15/canon-announces-1-inch-spad-sensor-ms-510-extreme-low-light-multi-purpose-camera/"},{"label":"Chida et al. / Canon（MDPI *Sensors* 2025年10月、5 μmピッチ1MP 3D-BSIカラーSPAD：25℃ DCR 3.9 cps・消費電力1.053 W）","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12608571/"},{"label":"Sony J. Ogi et al. / IEEE ISSCC 2021（ResearchGate：250fps・124 dB DR 3D積層画素並列光子カウンタSPAD・サブフレーム外挿HDR）","url":"https://www.researchgate.net/publication/350172286_75_A_250fps_124dB_Dynamic-Range_SPAD_Image_Sensor_Stacked_with_Pixel-Parallel_Photon_Counter_Employing_Sub-Frame_Extrapolating_Architecture_for_Motion_Artifact_Suppression"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (1)","url":"https://opg.optica.org/abstract.cfm?uri=optica-4-12-1474"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (2)","url":"https://www.researchgate.net/publication/350865712_A_019e-_rms_Read_Noise_167Mpixel_Stacked_Quanta_Image_Sensor_With_11_mm-Pitch_Backside_Illuminated_Pixels"},{"label":"Mordor Intelligence（2026年10月、産業・車載SPAD市場と3D積層量産投資動向）","url":"https://www.mordorintelligence.com/industry-reports/spad-imaging-sensors-for-industrial-vision-market"}],"beginnerTitle":"光の粒を数え上げ23段HDRを作る「超高速カウンタ頭脳層」","beginnerSummary":"受光チップのすぐ真下にある第2のシリコン層です。1つひとつの画素ごとに専用の「リセット装置」と「デジタル数取器」がびっしり入っており、光の粒が当たった回数や満タンになる速さを数ナノ秒単位で記録します。","beginnerPoints":["光の粒を検出した瞬間、数ナノ秒（10億分の数秒）で素早くリセットして次の光の粒に備えます。","太陽など強烈に明るい場所は「あっという間に満タンになった時間」から明るさを逆算するため、白飛びしない23段HDRが1回のシャッターで撮れます。","明るい昼間に全画素が猛スピードで反応して電池が急減しないよう、賢くカウントを間引く省エネ制御も搭載します。"],"beginnerCaution":"1MPで1 W超だった試作SPADの消費電力をフルサイズ大面積（20〜36MP）へ広げるには、微細プロセス化と高輝度時の適応クエンチ間引きが絶対条件です。","glossaryIds":["001","012","102","106"]}},{"id":"mirai-fh01-dram-ring-die","diagramType":"mirai_fh01_dram_ring_die","order":8,"miraiSubView":1,"swatchColor":"#4f46e5","groupKey":"fh01_silicon","assembledPos":[0,-0.95,0],"explodeOffset":[0,-2.5,0],"edgeOpacity":0.22,"title":"FH01-08. 第3積層ウェーハ：超高速サブフレーム積算DRAM＆48 TSV","subtitle":"Bottom Tier Wafer: High-Bandwidth Sub-Frame Integration DRAM & 48 Perimeter TSVs","category":"FH01 SPAD/QIS / 3層積層メモリ＆時空間統合層","plainAnalogy":"1秒間に何千枚もの超高速な光子マップを一時保存し、被写体の動きに合わせてブレずに合成する超大容量メモリー層です。","summary":"第2層ロジック直下に3層積層された広帯域フレームバッファDRAMダイと48本の外周シリコン貫通電極（TSV）。1,000〜10,000 fps級の超高速1-bit/多ビット・サブフレーム光子列を一時保持し、動体ブレのない時空間光子積算を可能にします。","opticsAndPhysics":["極暗所や高速動体シーンでは、1/30秒の露光をそのまま積算すると被写体ブレが生じます。内蔵DRAMへ毎秒数千枚の極短サブフレーム光子マップを蓄え、動きベクトルに沿って再整列（Motion-Compensated Photon Integration）してから積算します。","4つのクワドラントDRAMバンクが広帯域インターフェースで第2層ロジックと直結し、外部I/Oの消費電力を増やさずリアルタイム統計処理を実現します。","外周48本の銅TSVが電源・グランドと高速SLVS-EC出力を最短経路で下部パッケージへ逃がします。"],"formula":{"expression":"I_final(x,y) = Σ_{k=1}^{M} B_k(x + Δx_k, y + Δy_k)  (M = 64–1024 sub-frames)","description":"DRAM上のM枚の超高速サブフレームを動き補償しながら無ノイズ加算し、暗所でもブレない鮮鋭像を再構成します。"},"nextGenInnovation":"3層積層DRAMによる「露光後でもブレを止めてから光を集める」モーション補償フォトン積算基盤。","specs":[{"label":"積層構成","value":"3層3D積層（SPAD + Logic + DRAM）"},{"label":"サブフレーム速度","value":"1,000〜10,000 sub-fps（1-bit/多bit可変）"},{"label":"貫通配線","value":"外周48本 銅TSV（Through-Silicon Via）"},{"label":"内蔵帯域","value":"≥ 256 GB/s チップ内ダイレクト転送"}],"references":["J. Ma & E. Fossum / Gigajot — Multi-Bit & Single-Bit QIS Jot Frame Accumulation Architecture","Sony Semiconductor — 3-Layer Stacked CMOS/DRAM Image Sensor TSV Packaging Architecture"],"mirai":{"fhId":"FH01","volume":1,"badge":"量産民主化","eta":"2027 Q4〜2028 Q3","score":86,"axes":[18,15,18,19,16],"scoreRationale":"光子ショットノイズ限界へ迫る物理突破（18点）と暗闇の撮影体験革命（19点）が際立つ。一方、極暗所でのビニング必須性、SPADのDCR・高輝度消費電力、フルサイズ3D積層歩留まりの厳しさを織り込み量産民主化15点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"読み出しノイズ","current2026":"1.0〜2.7 e-rms","future2028":"0 e-rms（SPADデジタル計数）／0.15〜0.21 e-rms（QIS）"},{"metric":"単一露出DR","current2026":"84〜96 dB（14〜16段）","future2028":"125〜140 dB（20〜23段・サブフレーム外挿HDR）"},{"metric":"極暗所カラー撮影","current2026":"ISO 51,200〜102,400でノイズ床に埋没","future2028":"画素ビニング＋時間積算併用で0.0005 lux・ISO 400万相当カラー"},{"metric":"画素ピッチ＆高画素化","current2026":"3.7〜6 μm（24〜66MP）","future2028":"SPAD：4.9〜6.6 μm（20〜36MP）／QIS：1〜2 μmジョット統合"}],"sourceUrls":[{"label":"Newsshooter（2026年4月15日、Canon 1型3.2MP SPADカメラ「MS-510」発表：0.0006 lux極暗所カラー対応）","url":"https://www.newsshooter.com/2026/04/15/canon-announces-1-inch-spad-sensor-ms-510-extreme-low-light-multi-purpose-camera/"},{"label":"Chida et al. / Canon（MDPI *Sensors* 2025年10月、5 μmピッチ1MP 3D-BSIカラーSPAD：25℃ DCR 3.9 cps・消費電力1.053 W）","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12608571/"},{"label":"Sony J. Ogi et al. / IEEE ISSCC 2021（ResearchGate：250fps・124 dB DR 3D積層画素並列光子カウンタSPAD・サブフレーム外挿HDR）","url":"https://www.researchgate.net/publication/350172286_75_A_250fps_124dB_Dynamic-Range_SPAD_Image_Sensor_Stacked_with_Pixel-Parallel_Photon_Counter_Employing_Sub-Frame_Extrapolating_Architecture_for_Motion_Artifact_Suppression"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (1)","url":"https://opg.optica.org/abstract.cfm?uri=optica-4-12-1474"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (2)","url":"https://www.researchgate.net/publication/350865712_A_019e-_rms_Read_Noise_167Mpixel_Stacked_Quanta_Image_Sensor_With_11_mm-Pitch_Backside_Illuminated_Pixels"},{"label":"Mordor Intelligence（2026年10月、産業・車載SPAD市場と3D積層量産投資動向）","url":"https://www.mordorintelligence.com/industry-reports/spad-imaging-sensors-for-industrial-vision-market"}],"beginnerTitle":"毎秒数千コマの光子データを蓄える「3階建て底面メモリー層」","beginnerSummary":"暗闇で動く動物や手ブレを防ぎながら光を集めるため、センサーの最下階に超高速メモリー（DRAM）を丸ごと一体化しています。一瞬ごとの光の粒の位置を何百枚分も一時記録し、動きに合わせてピタッと重ね合わせます。","beginnerPoints":["4つの高速メモリーブロックが、毎秒数千回分の光子データをカメラ本体へ送る前にその場で受け止めます。","チップのフチを縦に貫く48本の銅のトンネル（TSV）で、下の基板へ最短距離で電力とデータをやり取りします。","「暗闇でシャッター速度を遅くするとブレる」という長年の弱点を、超高速コマ分け＋動き合わせ積算で緩和します。"],"beginnerCaution":"3枚もの大判フルサイズウェーハをすべて良品で重ねる3層積層は歩留まりコストが高いため、2028年時点では35〜55万円の中上位〜ハイエンド機から採用が始まります。","glossaryIds":["001","002","101","106"]}},{"id":"mirai-fh01-hv-chargepump-ring","diagramType":"mirai_fh01_hv_chargepump_ring","order":9,"miraiSubView":1,"swatchColor":"#0f766e","groupKey":"fh01_electronics","assembledPos":[0,1.45,0],"explodeOffset":[0,11,16],"edgeOpacity":0.22,"title":"FH01-09. 20〜28V 高耐圧バイアス昇圧チャージポンプ・カラー基板","subtitle":"20–28V Temperature-Compensated High-Voltage Bias Charge-Pump Perimeter Collar","category":"FH01 SPAD/QIS / 高電圧バイアス供給・温度補償回路","plainAnalogy":"SPADの「雪崩センサー」を正確に働かせるため、温度変化に合わせて20〜28 Vの高電圧を0.01 V単位で微調整し続ける専用電源リングです。","summary":"36×24 mm受光ダイ外周を囲むABF絶縁サブ基板上に、4基のQFN高電圧チャージポンプIC、4基のシールド昇圧インダクタ、および金めっき高耐圧給電トレースリングを統合したSPAD専用バイアス電源カラー。","opticsAndPhysics":["SPADの降伏電圧 V_BD はシリコン温度に対して約 +20〜30 mV/℃ の正の温度係数を持ちます。温度上昇時に印加電圧が固定のままだと過剰バイアス V_ex が低下し感度が変動します。","CuWヒートスラグ内蔵NTCサーミスタの温度データを受け、4隅のチャージポンプICが20〜28 Vの逆バイアスを±10 mV精度でリアルタイム追従制御します。","4方向からの対称給電（Star-Ring Power Delivery）により、高輝度シーンで大電流が流れても画面中央と四隅のV_exドロップ差（シェーディング）を防止します。"],"formula":{"expression":"V_bias(T) = V_BD(T_0) + α_T · (T - T_0) + V_ex  (α_T ≈ +25 mV/℃)","description":"温度係数α_Tを打ち消す動的バイアス制御により、寒冷地から炎天下まで一定の光子検出確率（PDP）を維持します。"},"nextGenInnovation":"パッケージ内近接4隅昇圧リングにより、カメラ本体メイン基板に高電圧配線を這わせず安全かつ低リップルな28 V駆動を実現。","specs":[{"label":"出力バイアス範囲","value":"20.0〜28.0 V DC（±10 mV 動的温度追従）"},{"label":"搭載IC・素子","value":"QFN昇圧チャージポンプ ×4 ＋ シールドインダクタ ×4"},{"label":"基板構造","value":"多層ABF高耐圧絶縁カラー（金めっきリング配線）"},{"label":"リップル電圧","value":"< 1.5 mVpp（全画素同時発火時）"}],"references":["Chida et al. / Canon, MDPI Sensors 2025 (PMC12608571) — SPAD Excess Bias Voltage & Thermal Stability","STMicroelectronics VL53L9 / Industrial SPAD High-Voltage Charge-Pump Regulation Architecture"],"mirai":{"fhId":"FH01","volume":1,"badge":"量産民主化","eta":"2027 Q4〜2028 Q3","score":86,"axes":[18,15,18,19,16],"scoreRationale":"光子ショットノイズ限界へ迫る物理突破（18点）と暗闇の撮影体験革命（19点）が際立つ。一方、極暗所でのビニング必須性、SPADのDCR・高輝度消費電力、フルサイズ3D積層歩留まりの厳しさを織り込み量産民主化15点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"読み出しノイズ","current2026":"1.0〜2.7 e-rms","future2028":"0 e-rms（SPADデジタル計数）／0.15〜0.21 e-rms（QIS）"},{"metric":"単一露出DR","current2026":"84〜96 dB（14〜16段）","future2028":"125〜140 dB（20〜23段・サブフレーム外挿HDR）"},{"metric":"極暗所カラー撮影","current2026":"ISO 51,200〜102,400でノイズ床に埋没","future2028":"画素ビニング＋時間積算併用で0.0005 lux・ISO 400万相当カラー"},{"metric":"画素ピッチ＆高画素化","current2026":"3.7〜6 μm（24〜66MP）","future2028":"SPAD：4.9〜6.6 μm（20〜36MP）／QIS：1〜2 μmジョット統合"}],"sourceUrls":[{"label":"Newsshooter（2026年4月15日、Canon 1型3.2MP SPADカメラ「MS-510」発表：0.0006 lux極暗所カラー対応）","url":"https://www.newsshooter.com/2026/04/15/canon-announces-1-inch-spad-sensor-ms-510-extreme-low-light-multi-purpose-camera/"},{"label":"Chida et al. / Canon（MDPI *Sensors* 2025年10月、5 μmピッチ1MP 3D-BSIカラーSPAD：25℃ DCR 3.9 cps・消費電力1.053 W）","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12608571/"},{"label":"Sony J. Ogi et al. / IEEE ISSCC 2021（ResearchGate：250fps・124 dB DR 3D積層画素並列光子カウンタSPAD・サブフレーム外挿HDR）","url":"https://www.researchgate.net/publication/350172286_75_A_250fps_124dB_Dynamic-Range_SPAD_Image_Sensor_Stacked_with_Pixel-Parallel_Photon_Counter_Employing_Sub-Frame_Extrapolating_Architecture_for_Motion_Artifact_Suppression"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (1)","url":"https://opg.optica.org/abstract.cfm?uri=optica-4-12-1474"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (2)","url":"https://www.researchgate.net/publication/350865712_A_019e-_rms_Read_Noise_167Mpixel_Stacked_Quanta_Image_Sensor_With_11_mm-Pitch_Backside_Illuminated_Pixels"},{"label":"Mordor Intelligence（2026年10月、産業・車載SPAD市場と3D積層量産投資動向）","url":"https://www.mordorintelligence.com/industry-reports/spad-imaging-sensors-for-industrial-vision-market"}],"beginnerTitle":"温度に合わせて20〜28Vを自動調整する「専用高圧リング」","beginnerSummary":"SPADが光の粒1個で反応するには20〜28 Vという少し高めの電圧が必要です。しかもセンサーが温まるとちょうどいい電圧がズレてしまうため、四隅に配置した4つの昇圧チップが温度計と連動して常にピタッと最適電圧を保ちます。","beginnerPoints":["センサーをぐるっと囲むエメラルド色のリング基板に、4つの小さな昇圧ICとコイルを対称に並べています。","真冬の雪山でも真夏の炎天下でも感度が狂わないよう、温度に応じて電圧を1/100ボルト単位で自動補正します。","高電圧をセンサー容器のすぐそばで作って完結させることで、カメラ内部のノイズ混入や安全リスクを最小化します。"],"beginnerCaution":"通常CMOS（1.8〜3.3 V）と違い20〜28 Vの高電圧が必要なため、絶縁距離の確保と明所大電流時の電圧降下対策が設計の要になります。","glossaryIds":["001","008","103"]}},{"id":"mirai-fh01-htcc-ceramic-pkg","diagramType":"mirai_fh01_htcc_ceramic_pkg","order":10,"miraiSubView":1,"swatchColor":"#475569","groupKey":"fh01_package","assembledPos":[0,-1.1,0],"explodeOffset":[0,-9.5,0],"edgeOpacity":0.24,"title":"FH01-10. 多層段付きHTCCアルミナセラミック気密パッケージ","subtitle":"Multi-Step Hollow-Cavity HTCC Alumina Ceramic Hermetic Package & LGA Grid","category":"FH01 SPAD/QIS / 高剛性セラミック気密筐体","plainAnalogy":"3階建ての精密シリコンチップを湿気や歪みから守り、階段状の段差に金線やコンデンサを整然と収める高強度セラミックの器です。","summary":"高温同時焼成セラミック（HTCCアルミナ）による56×44 mm多段キャビティパッケージ。中央の銀焼結ダイボンド床、2段目の金めっきワイヤーボンド棚、外周キャスタレーション検査端子、および底面LGAランド配列を一体化しています。","opticsAndPhysics":["アルミナセラミック（Al₂O₃、ヤング率 ≈ 370 GPa、CTE ≈ 6.8 ppm/K）は樹脂パッケージに比べ圧倒的な曲げ剛性とシリコン近接熱膨張係数を持ち、フルサイズ大判ダイの反り（像面湾曲誤差）を数ミクロン以内へ封じ込めます。","2段の階段状キャビティ構造により、中央の3層積層ダイ、中段の金ワイヤーボンド棚＋HVカラー、外縁のコバール気密溶接面を立体的に無干渉配置できます。","底面外周のLGA金めっきパッド群は低インダクタンス電源・制御系を接続し、中央開口はCuWヒートスラグ直結用に確保しています。"],"formula":{"expression":"ΔL/L = (CTE_pkg - CTE_Si) · ΔT  →  Die Warpage < 3 μm across 43.3 mm diagonal","description":"セラミックとシリコンの熱膨張整合により、フルサイズ対角43.3 mm全域でサブミクロン〜数μm級の超高平面度を維持します。"},"nextGenInnovation":"高電圧28 V絶縁と多層低インピーダンスGNDプレーンを内蔵したSPAD/QIS専用HTCCセラミックキャビティ。","specs":[{"label":"パッケージ外形","value":"56.0 × 44.0 × 7.5 mm（多段キャビティ）"},{"label":"基材","value":"HTCC高純度アルミナセラミック（多層タングステン配線）"},{"label":"ダイ接合","value":"高熱伝導・銀焼結（Ag Sinter）ダイボンド"},{"label":"底面端子","value":"外周LGA金めっきランド＋側面キャスタレーション"}],"references":["Kyocera / NTK High-Temperature Co-Fired Ceramic (HTCC) Full-Frame Image Sensor Cavity Package Standards","JEDEC JESD22-A104 Thermal Cycling & Hermetic Ceramic Optical Packaging Guidelines"],"mirai":{"fhId":"FH01","volume":1,"badge":"量産民主化","eta":"2027 Q4〜2028 Q3","score":86,"axes":[18,15,18,19,16],"scoreRationale":"光子ショットノイズ限界へ迫る物理突破（18点）と暗闇の撮影体験革命（19点）が際立つ。一方、極暗所でのビニング必須性、SPADのDCR・高輝度消費電力、フルサイズ3D積層歩留まりの厳しさを織り込み量産民主化15点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"読み出しノイズ","current2026":"1.0〜2.7 e-rms","future2028":"0 e-rms（SPADデジタル計数）／0.15〜0.21 e-rms（QIS）"},{"metric":"単一露出DR","current2026":"84〜96 dB（14〜16段）","future2028":"125〜140 dB（20〜23段・サブフレーム外挿HDR）"},{"metric":"極暗所カラー撮影","current2026":"ISO 51,200〜102,400でノイズ床に埋没","future2028":"画素ビニング＋時間積算併用で0.0005 lux・ISO 400万相当カラー"},{"metric":"画素ピッチ＆高画素化","current2026":"3.7〜6 μm（24〜66MP）","future2028":"SPAD：4.9〜6.6 μm（20〜36MP）／QIS：1〜2 μmジョット統合"}],"sourceUrls":[{"label":"Newsshooter（2026年4月15日、Canon 1型3.2MP SPADカメラ「MS-510」発表：0.0006 lux極暗所カラー対応）","url":"https://www.newsshooter.com/2026/04/15/canon-announces-1-inch-spad-sensor-ms-510-extreme-low-light-multi-purpose-camera/"},{"label":"Chida et al. / Canon（MDPI *Sensors* 2025年10月、5 μmピッチ1MP 3D-BSIカラーSPAD：25℃ DCR 3.9 cps・消費電力1.053 W）","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12608571/"},{"label":"Sony J. Ogi et al. / IEEE ISSCC 2021（ResearchGate：250fps・124 dB DR 3D積層画素並列光子カウンタSPAD・サブフレーム外挿HDR）","url":"https://www.researchgate.net/publication/350172286_75_A_250fps_124dB_Dynamic-Range_SPAD_Image_Sensor_Stacked_with_Pixel-Parallel_Photon_Counter_Employing_Sub-Frame_Extrapolating_Architecture_for_Motion_Artifact_Suppression"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (1)","url":"https://opg.optica.org/abstract.cfm?uri=optica-4-12-1474"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (2)","url":"https://www.researchgate.net/publication/350865712_A_019e-_rms_Read_Noise_167Mpixel_Stacked_Quanta_Image_Sensor_With_11_mm-Pitch_Backside_Illuminated_Pixels"},{"label":"Mordor Intelligence（2026年10月、産業・車載SPAD市場と3D積層量産投資動向）","url":"https://www.mordorintelligence.com/industry-reports/spad-imaging-sensors-for-industrial-vision-market"}],"beginnerTitle":"精密チップを1ミクロンも歪ませない「段付きセラミックの器」","beginnerSummary":"フルサイズセンサーは切手より大きい精密ガラス・シリコン板なので、温度変化でほんの少し反るだけでピントが狂ってしまいます。高強度な焼き物（アルミナセラミック）を階段状に成型した器に収めることで、圧倒的な平面性と気密性を守ります。","beginnerPoints":["内側が階段状になっており、底にシリコンチップ、中段に金色の配線棚とコンデンサ、最上段に気密ガラス窓がピタッと収まります。","底面の真ん中は熱を逃がす銅タングステン板が直結できるよう開けられ、その周りに金色の電極パッドが並びます。","側面には工場出荷時の検査に使う半円状の金めっき端子（キャスタレーション）を備えています。"],"beginnerCaution":"セラミックパッケージは樹脂モールドより高価ですが、大判フルサイズの平面精度と長期気密性を両立させるため上位機では不可欠な構造です。","glossaryIds":["001","101"]}},{"id":"mirai-fh01-gold-wirebond-frame","diagramType":"mirai_fh01_gold_wirebond_frame","order":11,"miraiSubView":1,"swatchColor":"#eab308","groupKey":"fh01_package","assembledPos":[0,2.7,0],"explodeOffset":[0,16.5,0],"edgeOpacity":0.2,"title":"FH01-11. コバール気密溶接枠＆全周64本3D金ワイヤーボンド","subtitle":"Kovar Seam-Weld Frame & 64 Parabolic 3D Gold Wirebond Interconnect Loops","category":"FH01 SPAD/QIS / 高信頼チップ-パッケージ結線＆封止枠","plainAnalogy":"チップの4辺からセラミックの棚へ、髪の毛より細い純金のアーチ線64本を美しく架け渡し、外周を金属溶接枠で密閉する精巧な結線部です。","summary":"36×24 mm受光・ロジックスタックの四辺金パッドとセラミック中段棚を結ぶ64本の放物線アーチ3D金ワイヤーボンドと、カバーガラスをレーザーシーム溶接するための最上縁コバール合金シールリングの複合アセンブリ。","opticsAndPhysics":["純金（4N Au）ワイヤーによる低ループ・放物線アーチ結線は、大判フルサイズダイとセラミック間の微小熱応力を弾性吸収しつつ、低抵抗・無腐食の長期信頼接続を提供します。","高周波SLVS-ECクロックとHVバイアスラインを分離配置し、ループ高さと長さを均一管理することで寄生インダクタンス（L ≈ 1.2 nH/loop）とクロストークを最小化します。","外周のコバール溶接リングは、不活性乾燥窒素雰囲気中でのカバーガラス・シーム封止を支えます。"],"formula":{"expression":"L_loop ≈ (μ_0 · l / 2π) · [ln(2l / r) - 0.75] ≈ 1.2 nH","description":"低背放物線ループ形状の統一により、高速スイッチング電流に伴う電源インダクタンスノイズを抑制します。"},"nextGenInnovation":"3D積層TSVと外周ロープロファイル金ワイヤーボンドのハイブリッド電源・信号配線アーキテクチャ。","specs":[{"label":"ワイヤー材質","value":"99.99%（4N）純金ボンドワイヤー（Ø25 μm級）"},{"label":"モデル表現本数","value":"全周64本 放物線3Dアーチ（4辺対称配列）"},{"label":"封止リング","value":"Ni/Auめっきコバール合金シーム溶接枠"},{"label":"ループ精度","value":"低背クリアランス保証（カバーガラス非接触）"}],"references":["MIL-STD-883 Method 2011 Wire Bond Pull Strength & Loop Geometry Reliability Standard","Sony Semiconductor Full-Frame Stacked Image Sensor Ceramic Wire-Bonding Architecture"],"mirai":{"fhId":"FH01","volume":1,"badge":"量産民主化","eta":"2027 Q4〜2028 Q3","score":86,"axes":[18,15,18,19,16],"scoreRationale":"光子ショットノイズ限界へ迫る物理突破（18点）と暗闇の撮影体験革命（19点）が際立つ。一方、極暗所でのビニング必須性、SPADのDCR・高輝度消費電力、フルサイズ3D積層歩留まりの厳しさを織り込み量産民主化15点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"読み出しノイズ","current2026":"1.0〜2.7 e-rms","future2028":"0 e-rms（SPADデジタル計数）／0.15〜0.21 e-rms（QIS）"},{"metric":"単一露出DR","current2026":"84〜96 dB（14〜16段）","future2028":"125〜140 dB（20〜23段・サブフレーム外挿HDR）"},{"metric":"極暗所カラー撮影","current2026":"ISO 51,200〜102,400でノイズ床に埋没","future2028":"画素ビニング＋時間積算併用で0.0005 lux・ISO 400万相当カラー"},{"metric":"画素ピッチ＆高画素化","current2026":"3.7〜6 μm（24〜66MP）","future2028":"SPAD：4.9〜6.6 μm（20〜36MP）／QIS：1〜2 μmジョット統合"}],"sourceUrls":[{"label":"Newsshooter（2026年4月15日、Canon 1型3.2MP SPADカメラ「MS-510」発表：0.0006 lux極暗所カラー対応）","url":"https://www.newsshooter.com/2026/04/15/canon-announces-1-inch-spad-sensor-ms-510-extreme-low-light-multi-purpose-camera/"},{"label":"Chida et al. / Canon（MDPI *Sensors* 2025年10月、5 μmピッチ1MP 3D-BSIカラーSPAD：25℃ DCR 3.9 cps・消費電力1.053 W）","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12608571/"},{"label":"Sony J. Ogi et al. / IEEE ISSCC 2021（ResearchGate：250fps・124 dB DR 3D積層画素並列光子カウンタSPAD・サブフレーム外挿HDR）","url":"https://www.researchgate.net/publication/350172286_75_A_250fps_124dB_Dynamic-Range_SPAD_Image_Sensor_Stacked_with_Pixel-Parallel_Photon_Counter_Employing_Sub-Frame_Extrapolating_Architecture_for_Motion_Artifact_Suppression"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (1)","url":"https://opg.optica.org/abstract.cfm?uri=optica-4-12-1474"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (2)","url":"https://www.researchgate.net/publication/350865712_A_019e-_rms_Read_Noise_167Mpixel_Stacked_Quanta_Image_Sensor_With_11_mm-Pitch_Backside_Illuminated_Pixels"},{"label":"Mordor Intelligence（2026年10月、産業・車載SPAD市場と3D積層量産投資動向）","url":"https://www.mordorintelligence.com/industry-reports/spad-imaging-sensors-for-industrial-vision-market"}],"beginnerTitle":"チップの四辺をつなぐ「64本の純金アーチ線＆密閉リング」","beginnerSummary":"シリコンチップの外周に並ぶ金色のパッドと、セラミック容器の段差の間を、髪の毛より細い純金のワイヤーが美しい放物線アーチを描いてつないでいます。上のガラス窓を傷つけないよう高さを揃えた、まさに時計職人級の微細配線です。","beginnerPoints":["柔らかい純金ワイヤーをわずかに山なり（アーチ状）に曲げることで、温度変化による膨張・収縮をバネのように吸収して断線を防ぎます。","3Dモデルを拡大してガラス窓越しにのぞき込むと、チップの四辺を囲む黄金のアーチ列を立体的に観察できます。","外側の銀灰色フレーム（コバール枠）は、上のガラス窓を隙間ゼロで気密溶接するための土台です。"],"beginnerCaution":"金線は極めて繊細なので、工場のクリーンルーム内で自動ボンディング装置により1秒あたり数十本という超高速・ミクロン精度で結線されます。","glossaryIds":["001","101","106"]}},{"id":"mirai-fh01-mlcc-decoupling-bank","diagramType":"mirai_fh01_mlcc_decoupling_bank","order":12,"miraiSubView":1,"swatchColor":"#c2852a","groupKey":"fh01_electronics","assembledPos":[0,2.15,0],"explodeOffset":[16,6.5,0],"edgeOpacity":0.18,"title":"FH01-12. パッケージ内蔵・超低ESL MLCCデカップリング銀行＆LDO","subtitle":"In-Package Ultra-Low-ESL 0201/0402 MLCC Decoupling Array (×36) & Dual Low-Noise LDOs","category":"FH01 SPAD/QIS / 瞬時電流供給＆電源ノイズ濾過層","plainAnalogy":"何百万画素が一斉に雪崩カウントを起こす瞬間の急激な電気不足を、チップのすぐ隣で瞬時に補う36個の極小ミニバッテリー群です。","summary":"セラミックパッケージ内段差に超高密度実装された36個の低ESL積層セラミックコンデンサ（MLCC）と2基の超低ノイズDFNリニアレギュレータ（LDO）。SPAD同時発火時のピコ秒級スパイク電流をチップ直近で供給・平滑化します。","opticsAndPhysics":["明るいシーンで数百万画素のSPADが同時にアバランシェ発火すると、数ナノ秒の間に鋭い過渡電流スパイク（di/dt）が発生します。","外部メイン基板からでは配線インダクタンスが大きすぎて電圧降下（V = L·di/dt）を止められないため、パッケージ内部のチップ数ミリ直近に36個の低ESL MLCCを包囲配置します。","左右の超低ノイズLDO（PSRR > 80 dB）が、TDC時間計測用PLLクロックとQIS/アナログ基準電源へ極めてクリーンな定電圧を供給します。"],"formula":{"expression":"ΔV_droop = L_loop · (di / dt) + ΔQ_avalanche / C_MLCC","description":"チップ直近のパッケージ内MLCC配置でループインダクタンスL_loopを極小化し、瞬間電圧ドロップを抑制します。"},"nextGenInnovation":"SPAD特有の瞬間大電流スパイクをパッケージ内で完結吸収する「インパッケージ電源インテグリティ（PI）」設計。","specs":[{"label":"搭載キャパシタ","value":"0201/0402 超低ESL MLCC ×36個（四辺包囲配置）"},{"label":"内蔵レギュレータ","value":"超低ノイズ DFN LDO ×2基（PSRR > 80 dB）"},{"label":"耐圧定格","value":"50 V高耐圧（HV系）＋ 6.3 V（ロジック系）混載"},{"label":"等価直列インダクタンス","value":"ESL < 120 pH / 素子"}],"references":["Murata Manufacturing — Low-ESL LW-Reversed MLCC for High-Speed CMOS/SPAD Power Integrity","IEEE ISSCC SPAD Power Delivery & Transient Current Decoupling Guidelines"],"mirai":{"fhId":"FH01","volume":1,"badge":"量産民主化","eta":"2027 Q4〜2028 Q3","score":86,"axes":[18,15,18,19,16],"scoreRationale":"光子ショットノイズ限界へ迫る物理突破（18点）と暗闇の撮影体験革命（19点）が際立つ。一方、極暗所でのビニング必須性、SPADのDCR・高輝度消費電力、フルサイズ3D積層歩留まりの厳しさを織り込み量産民主化15点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"読み出しノイズ","current2026":"1.0〜2.7 e-rms","future2028":"0 e-rms（SPADデジタル計数）／0.15〜0.21 e-rms（QIS）"},{"metric":"単一露出DR","current2026":"84〜96 dB（14〜16段）","future2028":"125〜140 dB（20〜23段・サブフレーム外挿HDR）"},{"metric":"極暗所カラー撮影","current2026":"ISO 51,200〜102,400でノイズ床に埋没","future2028":"画素ビニング＋時間積算併用で0.0005 lux・ISO 400万相当カラー"},{"metric":"画素ピッチ＆高画素化","current2026":"3.7〜6 μm（24〜66MP）","future2028":"SPAD：4.9〜6.6 μm（20〜36MP）／QIS：1〜2 μmジョット統合"}],"sourceUrls":[{"label":"Newsshooter（2026年4月15日、Canon 1型3.2MP SPADカメラ「MS-510」発表：0.0006 lux極暗所カラー対応）","url":"https://www.newsshooter.com/2026/04/15/canon-announces-1-inch-spad-sensor-ms-510-extreme-low-light-multi-purpose-camera/"},{"label":"Chida et al. / Canon（MDPI *Sensors* 2025年10月、5 μmピッチ1MP 3D-BSIカラーSPAD：25℃ DCR 3.9 cps・消費電力1.053 W）","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12608571/"},{"label":"Sony J. Ogi et al. / IEEE ISSCC 2021（ResearchGate：250fps・124 dB DR 3D積層画素並列光子カウンタSPAD・サブフレーム外挿HDR）","url":"https://www.researchgate.net/publication/350172286_75_A_250fps_124dB_Dynamic-Range_SPAD_Image_Sensor_Stacked_with_Pixel-Parallel_Photon_Counter_Employing_Sub-Frame_Extrapolating_Architecture_for_Motion_Artifact_Suppression"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (1)","url":"https://opg.optica.org/abstract.cfm?uri=optica-4-12-1474"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (2)","url":"https://www.researchgate.net/publication/350865712_A_019e-_rms_Read_Noise_167Mpixel_Stacked_Quanta_Image_Sensor_With_11_mm-Pitch_Backside_Illuminated_Pixels"},{"label":"Mordor Intelligence（2026年10月、産業・車載SPAD市場と3D積層量産投資動向）","url":"https://www.mordorintelligence.com/industry-reports/spad-imaging-sensors-for-industrial-vision-market"}],"beginnerTitle":"瞬間の電力不足を防ぐ「チップ直近36個の極小コンデンサ群」","beginnerSummary":"SPADセンサーは明るい場所で何百万もの画素が一斉にピカピカ反応するため、一瞬だけ強い電気を吸い込みます。カメラ本体の電池から送っていては間に合わないので、チップのすぐ横に36個の超小型コンデンサを並べて「電気の貯水池」を作っています。","beginnerPoints":["茶色い本体に銀色の両端端子が付いた極小部品（MLCC）が36個、チップの四辺をぐるっと囲んでいます。","左右の黒い小さなLDOチップは、電気の波をピタッと静かに整える「超静音・電圧安定フィルター」です。","この電源の安定化があるからこそ、ピコ秒単位の正確な光子カウントとノイズの少ない暗所画質が守られます。"],"beginnerCaution":"高電圧28 VラインのコンデンサはDCバイアス特性による容量低下が起きやすいため、高耐圧グレードの厳選が欠かせません。","glossaryIds":["001","012","101"]}},{"id":"mirai-fh01-slvs-fpc-harness","diagramType":"mirai_fh01_slvs_fpc_harness","order":13,"miraiSubView":1,"swatchColor":"#ea580c","groupKey":"fh01_io","assembledPos":[32.5,-1.6,0],"explodeOffset":[24,-5,0],"edgeOpacity":0.22,"title":"FH01-13. SLVS-EC 16レーン超高速S字フレキシブル基板（FPC）","subtitle":"SLVS-EC 16-Lane Differential High-Speed S-Curved Polyimide FPC Harness & ZIF Tail","category":"FH01 SPAD/QIS / 超広帯域センサー出力ハーネス","plainAnalogy":"手ブレ補正でセンサーが自在に動いても断線せず、膨大な単一光子カウントデータを映像エンジンへ瞬時に送るS字型の超高速リボン配線です。","summary":"低誘電ポリイミド基材によるS字屈曲16レーンSLVS-EC差動伝送FPCハーネス。導電性銀メッシュEMIシールド層、カーボン補強ZIFスティフナー、アイボリーZIFロックバー、および28極硬質金めっきコンタクトフィンガーを統合しています。","opticsAndPhysics":["フルサイズ20〜36MPの多ビット光子カウント＆高フレームレート出力を遅延なく画像処理エンジンへ送るため、100 Ω厳密差動インピーダンス整合された16レーンSLVS-EC（最大100 Gbps超クラス）を採用します。","IBIS（ボディ内5軸手ブレ補正）による±数mmの高速並進・回転運動を繰り返しても疲労破断しないよう、応力を分散する滑らかなS字ベンド形状で配線します。","背面にラミネートされた極薄EMIシールドフィルムが、高周波差動信号からの不要輻射と外部無線ノイズの侵入を遮断します。"],"formula":{"expression":"Z_diff = 100 Ω ± 5%  |  BW_total = 16 lanes × 6.4 Gbps ≈ 102.4 Gbps","description":"厳密差動インピーダンス管理された16レーンSLVS-ECにより、20〜23段HDRや高速サブフレーム出力をボトルネックなしで伝送します。"},"nextGenInnovation":"IBIS可動追従性と100 Gbps級フォトントランスポートを両立する次世代シールドS字FPC。","specs":[{"label":"伝送規格","value":"SLVS-EC 次世代16レーン差動（~100 Gbps級）"},{"label":"基材・構造","value":"低損失LCP/ポリイミド＋銀メッシュEMIシールド"},{"label":"終端コネクタ","value":"28極硬質金めっきZIFフィンガー＋カーボン補強板"},{"label":"屈曲耐久","value":"IBIS 5軸駆動 1,000万回以上疲労耐性"}],"references":["Sony Semiconductor Solutions SLVS-EC High-Speed Interface Specification (v3.0+ Differential Standard)","IPC-2223 Sectional Design Standard for Flexible Printed Boards (Impedance-Controlled S-Bend)"],"mirai":{"fhId":"FH01","volume":1,"badge":"量産民主化","eta":"2027 Q4〜2028 Q3","score":86,"axes":[18,15,18,19,16],"scoreRationale":"光子ショットノイズ限界へ迫る物理突破（18点）と暗闇の撮影体験革命（19点）が際立つ。一方、極暗所でのビニング必須性、SPADのDCR・高輝度消費電力、フルサイズ3D積層歩留まりの厳しさを織り込み量産民主化15点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"読み出しノイズ","current2026":"1.0〜2.7 e-rms","future2028":"0 e-rms（SPADデジタル計数）／0.15〜0.21 e-rms（QIS）"},{"metric":"単一露出DR","current2026":"84〜96 dB（14〜16段）","future2028":"125〜140 dB（20〜23段・サブフレーム外挿HDR）"},{"metric":"極暗所カラー撮影","current2026":"ISO 51,200〜102,400でノイズ床に埋没","future2028":"画素ビニング＋時間積算併用で0.0005 lux・ISO 400万相当カラー"},{"metric":"画素ピッチ＆高画素化","current2026":"3.7〜6 μm（24〜66MP）","future2028":"SPAD：4.9〜6.6 μm（20〜36MP）／QIS：1〜2 μmジョット統合"}],"sourceUrls":[{"label":"Newsshooter（2026年4月15日、Canon 1型3.2MP SPADカメラ「MS-510」発表：0.0006 lux極暗所カラー対応）","url":"https://www.newsshooter.com/2026/04/15/canon-announces-1-inch-spad-sensor-ms-510-extreme-low-light-multi-purpose-camera/"},{"label":"Chida et al. / Canon（MDPI *Sensors* 2025年10月、5 μmピッチ1MP 3D-BSIカラーSPAD：25℃ DCR 3.9 cps・消費電力1.053 W）","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12608571/"},{"label":"Sony J. Ogi et al. / IEEE ISSCC 2021（ResearchGate：250fps・124 dB DR 3D積層画素並列光子カウンタSPAD・サブフレーム外挿HDR）","url":"https://www.researchgate.net/publication/350172286_75_A_250fps_124dB_Dynamic-Range_SPAD_Image_Sensor_Stacked_with_Pixel-Parallel_Photon_Counter_Employing_Sub-Frame_Extrapolating_Architecture_for_Motion_Artifact_Suppression"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (1)","url":"https://opg.optica.org/abstract.cfm?uri=optica-4-12-1474"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (2)","url":"https://www.researchgate.net/publication/350865712_A_019e-_rms_Read_Noise_167Mpixel_Stacked_Quanta_Image_Sensor_With_11_mm-Pitch_Backside_Illuminated_Pixels"},{"label":"Mordor Intelligence（2026年10月、産業・車載SPAD市場と3D積層量産投資動向）","url":"https://www.mordorintelligence.com/industry-reports/spad-imaging-sensors-for-industrial-vision-market"}],"beginnerTitle":"手ブレ補正に追従する「100Gbps超高速S字リボン配線」","beginnerSummary":"センサーが数え上げた膨大な光子データを、カメラの頭脳（画像処理エンジン）へ一瞬で届けるオレンジ色の柔らかい配線ケーブルです。センサーが手ブレ補正で縦横無尽に動いても折れないよう、しなやかなS字カーブを描いています。","beginnerPoints":["先端には28本の金色の端子（ZIFフィンガー）が並び、カメラのメイン基板へワンタッチで確実にロックされます。","裏側に貼られた銀色のシールド膜が、超高速通信の電波ノイズが外へ漏れるのをガードします。","23段もの広い明暗データや高速連写データを詰まらせず流せる超太いデータ高速道路です。"],"beginnerCaution":"SPAD/QISの高速サブフレーム出力は従来CMOSよりデータ量が跳ね上がるため、オンチップDRAMでの事前統合と超高速FPC伝送の連携が不可欠です。","glossaryIds":["001","012","101"]}},{"id":"mirai-fh01-cuw-slug-spreader","diagramType":"mirai_fh01_cuw_slug_spreader","order":14,"miraiSubView":1,"swatchColor":"#b45309","groupKey":"fh01_thermal","assembledPos":[0,-3.72,0],"explodeOffset":[0,-16.5,0],"edgeOpacity":0.24,"title":"FH01-14. 銅タングステン（CuW）低膨張ヒートスラグ＆NTC温度計","subtitle":"Machined CuW Low-CTE Thermal Slug Spreader & Embedded Kelvin-Sense NTC Thermistor","category":"FH01 SPAD/QIS / 高効率放熱＆DCR温度監視機構","plainAnalogy":"昼間の激しいカウント発熱を素早く逃がしつつ、センサーの温度を0.05℃単位で見張って高電圧とノイズを安定させる特殊合金の放熱板です。","summary":"銅の高熱伝導性とタングステンの低熱膨張性を焼結複合したCuW（Cu20/W80級）精密ヒートスラグと、側方タブに実装された高精度NTCサーミスタ＋ケルビン4線式金リード線アセンブリ。","opticsAndPhysics":["SPADの暗計数率（DCR）はシリコン温度が約8〜10℃上昇するごとに約2倍へ増加します。さらに明所連続撮影では全画素クエンチ消費電力が数W規模の発熱源となります。","純銅は熱膨張係数（16.5 ppm/K）が大きすぎてセラミックを反らせてしまいますが、CuW合金（CTE ≈ 7.2 ppm/K、熱伝導率 ≈ 200 W/m·K）なら無歪みかつ高速に直下放熱できます。","一体タブのNTCサーミスタがダイ直下の実温度を常時計測し、FH01-09の20〜28 Vチャージポンプへ温度補償フィードバックを送ります。"],"formula":{"expression":"DCR(T) ≈ DCR(T_0) · 2^{(T - T_0) / ΔT_double}  (ΔT_double ≈ 8–10℃)","description":"SPAD暗計数率は温度に対して指数関数的に増大するため、CuW直結放熱と精密NTC温度計測が画質維持の生命線です。"},"nextGenInnovation":"フルサイズSPAD最大の課題である「明所発熱＆DCR温度ドリフト」を制圧する低CTE複合ヒートスラグ＋直近NTC統合。","specs":[{"label":"材質組成","value":"焼結 Cu20/W80 銅タングステン合金"},{"label":"熱伝導率 / CTE","value":"約 200 W/(m·K) / 7.2 ppm/K（セラミック整合）"},{"label":"内蔵温度センサー","value":"高精度NTCサーミスタ（±0.05℃分解能・金リード付）"},{"label":"表面加工","value":"はんだ応力緩和マイクロ溝加工"}],"references":["Chida et al. / Canon, MDPI Sensors 2025 (PMC12608571) — SPAD DCR Temperature Dependence & Power Dissipation","ASTM B702 Copper-Tungsten Electrical & Thermal Management Composite Standard"],"mirai":{"fhId":"FH01","volume":1,"badge":"量産民主化","eta":"2027 Q4〜2028 Q3","score":86,"axes":[18,15,18,19,16],"scoreRationale":"光子ショットノイズ限界へ迫る物理突破（18点）と暗闇の撮影体験革命（19点）が際立つ。一方、極暗所でのビニング必須性、SPADのDCR・高輝度消費電力、フルサイズ3D積層歩留まりの厳しさを織り込み量産民主化15点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"読み出しノイズ","current2026":"1.0〜2.7 e-rms","future2028":"0 e-rms（SPADデジタル計数）／0.15〜0.21 e-rms（QIS）"},{"metric":"単一露出DR","current2026":"84〜96 dB（14〜16段）","future2028":"125〜140 dB（20〜23段・サブフレーム外挿HDR）"},{"metric":"極暗所カラー撮影","current2026":"ISO 51,200〜102,400でノイズ床に埋没","future2028":"画素ビニング＋時間積算併用で0.0005 lux・ISO 400万相当カラー"},{"metric":"画素ピッチ＆高画素化","current2026":"3.7〜6 μm（24〜66MP）","future2028":"SPAD：4.9〜6.6 μm（20〜36MP）／QIS：1〜2 μmジョット統合"}],"sourceUrls":[{"label":"Newsshooter（2026年4月15日、Canon 1型3.2MP SPADカメラ「MS-510」発表：0.0006 lux極暗所カラー対応）","url":"https://www.newsshooter.com/2026/04/15/canon-announces-1-inch-spad-sensor-ms-510-extreme-low-light-multi-purpose-camera/"},{"label":"Chida et al. / Canon（MDPI *Sensors* 2025年10月、5 μmピッチ1MP 3D-BSIカラーSPAD：25℃ DCR 3.9 cps・消費電力1.053 W）","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12608571/"},{"label":"Sony J. Ogi et al. / IEEE ISSCC 2021（ResearchGate：250fps・124 dB DR 3D積層画素並列光子カウンタSPAD・サブフレーム外挿HDR）","url":"https://www.researchgate.net/publication/350172286_75_A_250fps_124dB_Dynamic-Range_SPAD_Image_Sensor_Stacked_with_Pixel-Parallel_Photon_Counter_Employing_Sub-Frame_Extrapolating_Architecture_for_Motion_Artifact_Suppression"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (1)","url":"https://opg.optica.org/abstract.cfm?uri=optica-4-12-1474"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (2)","url":"https://www.researchgate.net/publication/350865712_A_019e-_rms_Read_Noise_167Mpixel_Stacked_Quanta_Image_Sensor_With_11_mm-Pitch_Backside_Illuminated_Pixels"},{"label":"Mordor Intelligence（2026年10月、産業・車載SPAD市場と3D積層量産投資動向）","url":"https://www.mordorintelligence.com/industry-reports/spad-imaging-sensors-for-industrial-vision-market"}],"beginnerTitle":"熱を逃がして誤カウントを抑える「銅タングステン放熱板＆温度計」","beginnerSummary":"SPADセンサーは温度が上がると、光が当たっていないのに「光が来た！」と勘違いする誤カウント（暗計数）が増えてしまいます。そこで熱を素早く逃がしつつ温度変化で伸び縮みしにくい特殊金属板を裏側に密着させ、小さな温度計で常時見張っています。","beginnerPoints":["銅の「熱を逃がす力」とタングステンの「熱で伸びにくい力」を合体させたプロ仕様の特殊合金（CuW）です。","左側の小さな基板に乗った赤い極小チップが温度センサー（NTC）で、測った温度をすぐ上の高圧リングへ送って電圧を自動調整します。","昼間の連続動画撮影で生じる発熱を素早く裏側へ逃がし、夜の暗所撮影でもクリーンな黒を保ちます。"],"beginnerCaution":"フルサイズ大判SPADは明るい昼間に消費電力が跳ね上がりやすいため、この放熱ルートが弱いとすぐに高温ノイズが増えてしまいます。","glossaryIds":["001","008","101"]}},{"id":"mirai-fh01-graphite-thermal-pad","diagramType":"mirai_fh01_graphite_thermal_pad","order":15,"miraiSubView":1,"swatchColor":"#0ea5e9","groupKey":"fh01_thermal","assembledPos":[0,-4.65,0],"explodeOffset":[0,-23.5,0],"edgeOpacity":0.2,"title":"FH01-15. 熱分解グラファイトシート（PGS）＆高弾性TIMパッド","subtitle":"Anisotropic Pyrolytic Graphite Sheet (PGS) & Compliant Silicone Waffle TIM Interface","category":"FH01 SPAD/QIS / 面内熱拡散＆無応力熱結合層","plainAnalogy":"熱い1点に熱が溜まらないよう銅の4倍の速さで横へ広げ、クッションのように優しく土台プレートへ熱を伝えるハイテク放熱シートです。","summary":"面内熱伝導率1,500 W/(m·K)超を誇る熱分解グラファイトシート（PGS）と、マイクロワッフル溝付き高熱伝導シリコーンTIMパッドの2層熱インターフェース。ホットスポットを均一化しつつ、シャッター振動や締付応力を遮断します。","opticsAndPhysics":["PGS（グラファイト結晶配向シート）は面内方向へ純銅の約3.8倍の速度で熱を拡散させ、SPADダイ中央の局所的な高温ホットスポット（暗計数DCRムラ）を解消します。","上層の柔軟シリコーンTIM（熱伝導率 ≥ 6 W/m·K）がCuWスラグ底面の微細凹凸を無空隙で埋め、空気層による熱抵抗を排除しつつ、ベースプレート締結応力がセンサー面へ伝わるのを防ぎます。"],"formula":{"expression":"k_in-plane(PGS) ≈ 1,500 W/(m·K)  ≫  k_Cu ≈ 398 W/(m·K)","description":"異方性グラファイトの圧倒的な面内熱拡散により、36×24 mm全面のDCR温度均一性を±0.5℃以内へ抑えます。"},"nextGenInnovation":"大面積フルサイズSPADの画面内暗計数ムラ（熱シェーディング）を根絶する面内超拡散＋無応力TIM構造。","specs":[{"label":"PGS面内熱伝導率","value":"約 1,500 W/(m·K)（厚さ 0.36 mm 積層）"},{"label":"TIMインターフェース","value":"柔軟シリコーンワッフルパッド（k ≥ 6 W/m·K）"},{"label":"面内温度偏差","value":"≤ ±0.5℃（36×24 mm全面）"},{"label":"応力絶縁性","value":"硬度 Shore 00-45（ダイ歪み伝播遮断）"}],"references":["Panasonic Industry Pyrolytic Graphite Sheet (PGS) EYGS Series Anisotropic Thermal Datasheet","Sony α-Series Sigma-Shaped Graphite & Silicone TIM Thermal Routing Architecture"],"mirai":{"fhId":"FH01","volume":1,"badge":"量産民主化","eta":"2027 Q4〜2028 Q3","score":86,"axes":[18,15,18,19,16],"scoreRationale":"光子ショットノイズ限界へ迫る物理突破（18点）と暗闇の撮影体験革命（19点）が際立つ。一方、極暗所でのビニング必須性、SPADのDCR・高輝度消費電力、フルサイズ3D積層歩留まりの厳しさを織り込み量産民主化15点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"読み出しノイズ","current2026":"1.0〜2.7 e-rms","future2028":"0 e-rms（SPADデジタル計数）／0.15〜0.21 e-rms（QIS）"},{"metric":"単一露出DR","current2026":"84〜96 dB（14〜16段）","future2028":"125〜140 dB（20〜23段・サブフレーム外挿HDR）"},{"metric":"極暗所カラー撮影","current2026":"ISO 51,200〜102,400でノイズ床に埋没","future2028":"画素ビニング＋時間積算併用で0.0005 lux・ISO 400万相当カラー"},{"metric":"画素ピッチ＆高画素化","current2026":"3.7〜6 μm（24〜66MP）","future2028":"SPAD：4.9〜6.6 μm（20〜36MP）／QIS：1〜2 μmジョット統合"}],"sourceUrls":[{"label":"Newsshooter（2026年4月15日、Canon 1型3.2MP SPADカメラ「MS-510」発表：0.0006 lux極暗所カラー対応）","url":"https://www.newsshooter.com/2026/04/15/canon-announces-1-inch-spad-sensor-ms-510-extreme-low-light-multi-purpose-camera/"},{"label":"Chida et al. / Canon（MDPI *Sensors* 2025年10月、5 μmピッチ1MP 3D-BSIカラーSPAD：25℃ DCR 3.9 cps・消費電力1.053 W）","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12608571/"},{"label":"Sony J. Ogi et al. / IEEE ISSCC 2021（ResearchGate：250fps・124 dB DR 3D積層画素並列光子カウンタSPAD・サブフレーム外挿HDR）","url":"https://www.researchgate.net/publication/350172286_75_A_250fps_124dB_Dynamic-Range_SPAD_Image_Sensor_Stacked_with_Pixel-Parallel_Photon_Counter_Employing_Sub-Frame_Extrapolating_Architecture_for_Motion_Artifact_Suppression"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (1)","url":"https://opg.optica.org/abstract.cfm?uri=optica-4-12-1474"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (2)","url":"https://www.researchgate.net/publication/350865712_A_019e-_rms_Read_Noise_167Mpixel_Stacked_Quanta_Image_Sensor_With_11_mm-Pitch_Backside_Illuminated_Pixels"},{"label":"Mordor Intelligence（2026年10月、産業・車載SPAD市場と3D積層量産投資動向）","url":"https://www.mordorintelligence.com/industry-reports/spad-imaging-sensors-for-industrial-vision-market"}],"beginnerTitle":"熱を瞬時に横へ広げる「グラファイト拡散シート＆柔軟パッド」","beginnerSummary":"センサーの真ん中だけ熱くなると、写真の真ん中だけザラザラする「熱ムラ」が起きてしまいます。銅の約4倍の速さで熱を横へ広げる黒いグラファイトシートと、柔らかい水色の放熱クッションで熱を均一に逃がします。","beginnerPoints":["水色の柔軟パッド（TIM）が金属板どうしのわずかな隙間を埋め、熱の詰まりをなくします。","下の黒いグラファイトシート（PGS）が、中央に集まった熱を全面へ素早く広げて冷やしやすくします。","クッション性があるため、底板をネジで強く締めても繊細なセンサーチップへ無理な力がかかりません。"],"beginnerCaution":"SPADは従来のCMOS以上に温度ムラが画質（暗計数ムラ）へ直結しやすいため、面内を均一に冷やす設計が非常に重要です。","glossaryIds":["001","008"]}},{"id":"mirai-fh01-precision-mount-base","diagramType":"mirai_fh01_precision_mount_base","order":16,"miraiSubView":1,"swatchColor":"#64748b","groupKey":"fh01_thermal","assembledPos":[0,-5.8,0],"explodeOffset":[0,-31,0],"edgeOpacity":0.26,"title":"FH01-16. CNC 3点基準マウントベースプレート＆M1.4トルクスボルト","subtitle":"CNC Machined Magnesium 3-Point Kinematic Datum Baseplate, Brass Shims & 6× M1.4 Torx Bolts","category":"FH01 SPAD/QIS / 3点キネマティック基準＆締結骨格","plainAnalogy":"レンズに対してセンサー面を1ミクロンの傾きもなくピタッと固定し、6本の精密トルクスネジと3点の調整シムで支える強固な土台です。","summary":"5軸CNC加工されたマグネシウム合金マウントベースプレート。3点キネマティック基準ボス＋真鍮チルト調整シム、底面剛性補強リブ、および6本の時計職人級M1.4ステンレス・トルクスボルトで構成される最終基準シャーシです。","opticsAndPhysics":["フルサイズ大口径F1.2レンズの焦点深度はわずか数ミクロンであるため、センサーのフランジバックと傾き（チルト）を3点キネマティック座面＋ミクロン単位の真鍮シムで光学ベンチ調整します。","マグネシウム合金（比剛性・減衰性に優れる）の軽量高剛性構造と裏面補強フレームにより、IBIS可動ステージ搭載時の慣性質量を最小化します。","6本のM1.4精密ボルト＋チタン座金ワッシャーが均等な締結トルクで全16層スタックを一体固定します。"],"formula":{"expression":"Δz_tilt = (D_sensor / 2) · tan(θ_tilt) < 2.0 μm  (F1.2 Depth of Focus)","description":"3点基準シム調整により、対角43.3 mm全域の受光面傾きをF1.2開放焦点深度内へ厳密収束させます。"},"nextGenInnovation":"IBIS超軽量駆動とサブミクロン平面基準を両立するマグネシウムCNC 3点キネマティック土台。","specs":[{"label":"プレート外形","value":"62.8 × 50.8 × 1.48 mm（裏面補強リブ付）"},{"label":"基準調整機構","value":"3点ステンレス基準ボス＋真鍮マイクロシム"},{"label":"締結ボルト","value":"M1.4 ステンレス精密トルクスボルト ×6 ＋ チタン座金"},{"label":"チルト公差","value":"≤ ±2.0 μm（全画面フランジ基準）"}],"references":["ISO 2768-fH Precision CNC Machining Tolerances & 3-Point Kinematic Optical Mount Design","Sony E-Mount Full-Frame IBIS Sensor Carrier Datum & Tilt Calibration Standard"],"mirai":{"fhId":"FH01","volume":1,"badge":"量産民主化","eta":"2027 Q4〜2028 Q3","score":86,"axes":[18,15,18,19,16],"scoreRationale":"光子ショットノイズ限界へ迫る物理突破（18点）と暗闇の撮影体験革命（19点）が際立つ。一方、極暗所でのビニング必須性、SPADのDCR・高輝度消費電力、フルサイズ3D積層歩留まりの厳しさを織り込み量産民主化15点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"読み出しノイズ","current2026":"1.0〜2.7 e-rms","future2028":"0 e-rms（SPADデジタル計数）／0.15〜0.21 e-rms（QIS）"},{"metric":"単一露出DR","current2026":"84〜96 dB（14〜16段）","future2028":"125〜140 dB（20〜23段・サブフレーム外挿HDR）"},{"metric":"極暗所カラー撮影","current2026":"ISO 51,200〜102,400でノイズ床に埋没","future2028":"画素ビニング＋時間積算併用で0.0005 lux・ISO 400万相当カラー"},{"metric":"画素ピッチ＆高画素化","current2026":"3.7〜6 μm（24〜66MP）","future2028":"SPAD：4.9〜6.6 μm（20〜36MP）／QIS：1〜2 μmジョット統合"}],"sourceUrls":[{"label":"Newsshooter（2026年4月15日、Canon 1型3.2MP SPADカメラ「MS-510」発表：0.0006 lux極暗所カラー対応）","url":"https://www.newsshooter.com/2026/04/15/canon-announces-1-inch-spad-sensor-ms-510-extreme-low-light-multi-purpose-camera/"},{"label":"Chida et al. / Canon（MDPI *Sensors* 2025年10月、5 μmピッチ1MP 3D-BSIカラーSPAD：25℃ DCR 3.9 cps・消費電力1.053 W）","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12608571/"},{"label":"Sony J. Ogi et al. / IEEE ISSCC 2021（ResearchGate：250fps・124 dB DR 3D積層画素並列光子カウンタSPAD・サブフレーム外挿HDR）","url":"https://www.researchgate.net/publication/350172286_75_A_250fps_124dB_Dynamic-Range_SPAD_Image_Sensor_Stacked_with_Pixel-Parallel_Photon_Counter_Employing_Sub-Frame_Extrapolating_Architecture_for_Motion_Artifact_Suppression"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (1)","url":"https://opg.optica.org/abstract.cfm?uri=optica-4-12-1474"},{"label":"J. Ma & E. Fossum / Gigajot QIS一次研究（*Optica* 2017：1Mジョット0.21 e-rms、1.1 μm 16.7MP積層QIS 0.19 e-rms） (2)","url":"https://www.researchgate.net/publication/350865712_A_019e-_rms_Read_Noise_167Mpixel_Stacked_Quanta_Image_Sensor_With_11_mm-Pitch_Backside_Illuminated_Pixels"},{"label":"Mordor Intelligence（2026年10月、産業・車載SPAD市場と3D積層量産投資動向）","url":"https://www.mordorintelligence.com/industry-reports/spad-imaging-sensors-for-industrial-vision-market"}],"beginnerTitle":"ピント面の傾きをゼロに保つ「3点基準土台＆6本の精密ボルト」","beginnerSummary":"全16層の精密な部品を一番下からガッチリ支え、カメラ本体の手ブレ補正ステージへ取り付けるマグネシウム合金の土台です。3つの丸い台座に薄い真鍮プレートを挟み、ピント面のわずかな傾きまでミクロン単位で追い込みます。","beginnerPoints":["軽くて頑丈なマグネシウム合金の板に、6本のステンレス精密ボルトとチタン座金が整然と収まっています。","三角形に並んだ3つの台座（キネマティック基準）で支えることで、ガタつきや歪みのない完璧な平面を出します。","これでFH01の上から下まで全16層が一体となり、2028年の単一光子フルサイズモジュールが完成します。"],"beginnerCaution":"センサーの傾きが数ミクロンずれるだけで大口径レンズの片ボケにつながるため、工場ではレーザー干渉計で1台ずつシム厚を調整します。","glossaryIds":["001","101"]}},{"id":"mirai-fh02-optical-hood-bezel","diagramType":"mirai_fh02_optical_hood_bezel","order":17,"miraiSubView":2,"swatchColor":"#334155","groupKey":"fh02_encapsulation","assembledPos":[0,6.15,0],"explodeOffset":[0,39.5,0],"edgeOpacity":0.26,"title":"FH02-01. CNC光学フードベゼル＆耐UV・防湿ガスケット","subtitle":"CNC Machined Optical Hood Bezel, Titanium Trim & Perimeter UV/Moisture EPDM Gasket","category":"FH02 3層垂直RGB / 最前面保護＆防湿遮光枠","plainAnalogy":"湿気や紫外線に繊細なペロブスカイト膜を外敵から守り、前面に青・緑・赤の3層シンボルを刻んだ精密ベゼル枠です。","summary":"ベイヤー配列を撤廃した3層垂直RGBペロブスカイトセンサー最前面のCNC削り出し光学ベゼル。チタン開口トリム、連続EPDM防湿圧縮ガスケット、および3波長垂直分離を象徴するRGBマイクロインレイを備えます。","opticsAndPhysics":["ハロゲン化ペロブスカイト／有機薄膜は水分・酸素・近紫外（<380 nm）による光分解が劣化主因となるため、最前面ベゼル直下から連続EPDMガスケットで物理的防湿バリアを形成します。","開口内径のチタン製面取りトリムが36×24 mm受光領域を正確に規定し、斜入射光による縁部色ズレ（バンドギャップ光路差）を最小化します。","OLPF（光学ローパスフィルター）が物理的に不要となるため、ベゼル直下から受光面までの光路長を従来機より短縮できます。"],"formula":{"expression":"OLPF = Removed (0% Moiré)  |  UV Cutoff λ < 395 nm","description":"1画素完全RGB取得によりローパスフィルターが不要となり、防湿・UVカット保護へ最前面構造を最適化できます。"},"nextGenInnovation":"ローパスフィルター撤廃＋防湿ガスケット統合による薄型・高鮮鋭ペロブスカイト受光開口設計。","specs":[{"label":"外形寸法","value":"58.4 × 46.4 × 1.38 mm"},{"label":"防湿シール","value":"連続圧縮EPDM防湿・防塵ガスケット"},{"label":"光学開口","value":"39.2 × 27.2 mm（チタン面取りトリム）"},{"label":"OLPF要否","value":"完全不要（1画素RGB同時取得で偽色ゼロ）"}],"references":["ETH Zurich / Empa, Nature 642:592–598 (2025-06-18, PMC12176651) — Vertically Stacked Monolithic Perovskite Colour Photodetectors","IEC 60529 / JEDEC Moisture Protection Guidelines for Thin-Film Photodetector Packaging"],"mirai":{"fhId":"FH02","volume":1,"badge":"超知能加速","eta":"2028 Q2〜2028 Q4","score":86,"axes":[18,13,19,18,18],"scoreRationale":"ベイヤー配列撤廃＋Foveon超えの急峻な色分離という構造優位性（19点）と物理突破（18点）は圧巻。一方、透明電極ロス（光利用率200〜250%級が物理上限）、現行試作の暗電流5桁ギャップ、鉛フリー化、PVD多層微細ビアの量産難度を厳格に見積もり量産民主化13点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"白色光・実効光利用率","current2026":"約25〜28%（CFで2/3吸収廃棄）","future2028":"実証47〜53%→目標60〜75%（実効2.0〜2.8倍・+1〜1.5段）"},{"metric":"色分離・偽色・モアレ","current2026":"デモザイク補間必須・偽色/モアレ発生","future2028":"1画素で完全RGB取得・Foveon比で極めて高い色純度"},{"metric":"光電変換と回路の構造","current2026":"PDと回路が面積を奪い合う","future2028":"薄膜光電変換層とCMOS回路が完全独立積層（GS容易）"},{"metric":"暗電流・環境規制ハードル","current2026":"室温0.02〜0.05 e-/s/pix・完全無毒Si","future2028":"現行試作暗電流5桁高＆鉛使用→ASI鉛フリー・低暗電流化必須"}],"sourceUrls":[{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (1)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12176651/"},{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (2)","url":"https://ethz.ch/en/news-and-events/eth-news/news/2025/06/better-images-for-humans-and-computers.html"},{"label":"Panasonic Holdings 公式プレスリリース（2023年3月17日、単層OPF有機センサー＋カラーフィルターによる600 nm透過1%未満・120 dB同時HDR・グローバルシャッター基盤実証）","url":"https://news.panasonic.com/global/topics/13982"},{"label":"arXiv（2026年9月、\\"PeroMAS: A Multi-agent System of Perovskite Material Discovery\\" — マルチエージェントAIによるペロブスカイト材料設計の先行研究）","url":"https://arxiv.org/html/2602.13312v2"}],"beginnerTitle":"3層ペロブスカイトを守る「防湿ガスケット付き光学ベゼル」","beginnerSummary":"ペロブスカイトや有機薄膜は光を吸収する力が抜群な反面、湿気や紫外線が苦手です。この最前面の金属フレームは裏側に黒い防湿パッキンをぐるっと備え、3層の宝石のような光電膜を10年単位で守る入り口の盾になります。","beginnerPoints":["前面の「青・緑・赤」の3つの小さなカラーチップが、色セロハンを使わず縦に3層で色分けするFH02の証です。","従来のカメラでモアレを防ぐために必須だった「ローパスフィルター（わざと少しぼかす板）」が要らなくなります。","内側の明るいチタン枠と裏側の防湿ゴムパッキンが、外気の湿気侵入を二重に食い止めます。"],"beginnerCaution":"3層垂直センサーは偽色やモアレが物理的に出ない一方、ペロブスカイト材料の長期耐湿・耐UV保護が実用化の最重要テーマになります。","glossaryIds":["003","004","101"]}},{"id":"mirai-fh02-ald-tfe-barrier","diagramType":"mirai_fh02_ald_tfe_barrier","order":18,"miraiSubView":2,"swatchColor":"#38bdf8","groupKey":"fh02_encapsulation","assembledPos":[0,4.95,0],"explodeOffset":[0,33,0],"edgeOpacity":0.16,"title":"FH02-02. 多層ALD/TFE超防湿バリア封止ガラス窓（10年耐久）","subtitle":"Multi-Layer Atomic Layer Deposition (ALD) / TFE Ultra-Barrier Optical Window","category":"FH02 3層垂直RGB / 原子層超防湿・UVカット窓","plainAnalogy":"水分子1個すら通さない原子レベルの超極薄バリア膜を何重にも重ね、ペロブスカイト膜の寿命を10年クラスへ延ばす特注ガラス窓です。","summary":"水蒸気透過率（WVTR）10⁻⁶ g/(m²·day)級を達成するAl₂O₃/TiO₂交互多層ALD（原子層堆積）薄膜封止（TFE）一体カバーガラス。395 nm以下の劣化紫外光を急峻カットしつつ可視400〜700 nmを99%超透過します。","opticsAndPhysics":["ペロブスカイト結晶は微量水分（ppmレベル）と酸素・紫外線が同時に存在するとイオン移動・相分離を起こすため、OLEDディスプレイ以上に厳格なWVTR ≤ 10⁻⁶ g/(m²·day)の超防湿封止が必須です。","無ピンホールの無機Al₂O₃/SiN_x層と応力緩和有機バッファ層を交互積層するTFE（Thin-Film Encapsulation）により、水分拡散経路を極端に迂回させて10年級寿命を実現します。","外周のコバール枠＋パリレン耐湿シールリングが、側面からの横方向水分侵入（Edge Ingress）を完全遮断します。"],"formula":{"expression":"WVTR ≤ 10^-6 g/(m^2·day)  |  UV Cut < 395 nm (OD > 4)","description":"多層ALD/TFE超防湿バリアとUVシャープカットにより、ペロブスカイト3層膜の10年実用耐久性を担保します。"},"nextGenInnovation":"OLED量産で熟成したTFE/ALD超防湿封止をフルサイズ撮像素子へ応用し、ペロブスカイト民生化の最大障壁を突破。","specs":[{"label":"水蒸気透過率","value":"WVTR ≤ 10⁻⁶ g/(m²·day)（多層ALD/TFE）"},{"label":"光学特性","value":"400–700 nm 透過率 > 99% / <395 nm UV遮断"},{"label":"側面封止","value":"コバール枠＋パリレン耐湿二重シール"},{"label":"目標耐久寿命","value":"10年以上（85℃/85%RH 加速試験準拠）"}],"references":["ETH Zurich / Empa, Nature 642:592–598 (2025) — Long-Term Encapsulation Roadmap for Perovskite Photodetectors","ALD Al2O3/TiO2 Multi-Layer Thin-Film Encapsulation (TFE) WVTR 10^-6 g/m^2/day Standards"],"mirai":{"fhId":"FH02","volume":1,"badge":"超知能加速","eta":"2028 Q2〜2028 Q4","score":86,"axes":[18,13,19,18,18],"scoreRationale":"ベイヤー配列撤廃＋Foveon超えの急峻な色分離という構造優位性（19点）と物理突破（18点）は圧巻。一方、透明電極ロス（光利用率200〜250%級が物理上限）、現行試作の暗電流5桁ギャップ、鉛フリー化、PVD多層微細ビアの量産難度を厳格に見積もり量産民主化13点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"白色光・実効光利用率","current2026":"約25〜28%（CFで2/3吸収廃棄）","future2028":"実証47〜53%→目標60〜75%（実効2.0〜2.8倍・+1〜1.5段）"},{"metric":"色分離・偽色・モアレ","current2026":"デモザイク補間必須・偽色/モアレ発生","future2028":"1画素で完全RGB取得・Foveon比で極めて高い色純度"},{"metric":"光電変換と回路の構造","current2026":"PDと回路が面積を奪い合う","future2028":"薄膜光電変換層とCMOS回路が完全独立積層（GS容易）"},{"metric":"暗電流・環境規制ハードル","current2026":"室温0.02〜0.05 e-/s/pix・完全無毒Si","future2028":"現行試作暗電流5桁高＆鉛使用→ASI鉛フリー・低暗電流化必須"}],"sourceUrls":[{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (1)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12176651/"},{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (2)","url":"https://ethz.ch/en/news-and-events/eth-news/news/2025/06/better-images-for-humans-and-computers.html"},{"label":"Panasonic Holdings 公式プレスリリース（2023年3月17日、単層OPF有機センサー＋カラーフィルターによる600 nm透過1%未満・120 dB同時HDR・グローバルシャッター基盤実証）","url":"https://news.panasonic.com/global/topics/13982"},{"label":"arXiv（2026年9月、\\"PeroMAS: A Multi-agent System of Perovskite Material Discovery\\" — マルチエージェントAIによるペロブスカイト材料設計の先行研究）","url":"https://arxiv.org/html/2602.13312v2"}],"beginnerTitle":"水分子1個も通さない「原子レベル超防湿ガラス窓（ALD/TFE）」","beginnerSummary":"ペロブスカイトの弱点である「湿気・酸素・紫外線」を10年間シャットアウトするための超ハイテクガラス窓です。スマホの有機EL画面を守る技術を応用し、原子を1層ずつ並べるALD成膜で完璧なバリアを張っています。","beginnerPoints":["水蒸気の通り抜け量を100万分の1グラム以下（1日あたり）に抑える超防湿コーティングが施されています。","写真に不要で膜を傷める紫外線（395 nm以下）だけをスパッとカットし、青・緑・赤の可視光は綺麗に素通しします。","フチを二重の金属・樹脂リングで固め、横からのじわじわした湿気侵入も徹底ブロックします。"],"beginnerCaution":"2025年のNature論文時点では研究室での試作段階であり、この10年耐久の量産封止技術の確立が2028年実用化の必須条件です。","glossaryIds":["004","101","108"]}},{"id":"mirai-fh02-top-ito-electrode","diagramType":"mirai_fh02_top_ito_electrode","order":19,"miraiSubView":2,"swatchColor":"#7dd3fc","groupKey":"fh02_rgb_stack","assembledPos":[0,3.6,0],"explodeOffset":[0,27,0],"edgeOpacity":0.18,"title":"FH02-03. 最上層・極薄透明ITO共通電極＆銀バスバー枠","subtitle":"Ultra-Thin Low-Loss Top ITO/IZO Transparent Common Electrode & Silver Collector Busbar","category":"FH02 3層垂直RGB / 最上部透明バイアス電極","plainAnalogy":"光を通す透明な電気のシートで、青・緑・赤3層のてっぺん全体へ均一に電圧をかける極薄の透明電極です。","summary":"3層垂直ペロブスカイトスタックの最上面にスパッタ成膜された極薄透明導電膜（ITO/IZO）と、外周を囲む低抵抗銀（Ag）バスバー電極。透明電極による光学損失を最小限に抑えながら全面へ均一な逆バイアス電界を印加します。","opticsAndPhysics":["3層垂直センサーでは各層の上下に計4〜6界面の透明電極が必要なため、1層あたりの透過率を92%→96%超へ引き上げることが、実効光利用率60〜75%（ベイヤー比2.0〜2.8倍）達成の決定的要因となります。","極薄化するとシート抵抗が上がって画面中央の応答が遅くなるため、外周の銀バスバー配線で直列抵抗ドロップを補償します。","下層のペロブスカイト膜をプラズマ損傷させない低温ソフト・スパッタ（またはパルスレーザー堆積）プロセスが量産の要点です。"],"formula":{"expression":"T_stack = Π_{i=1}^{N} T_ITO,i ≈ 0.65–0.80  (4–6 Transparent Interfaces)","description":"透明電極1層ごとの透過率と屈折率整合の最適化が、3層合算の実効光利用率（200〜280%）の物理上限を左右します。"},"nextGenInnovation":"屈折率整合極薄IZO/ITO透明電極により、複数界面の多重反射ロスを極小化。","specs":[{"label":"電極材質","value":"極薄低温スパッタ ITO / IZO 透明導電膜"},{"label":"単層光透過率","value":"≥ 92〜95%（400–700 nm可視全域）"},{"label":"シート抵抗","value":"≤ 15 Ω/sq（外周銀バスバー併用）"},{"label":"成膜温度","value":"< 100℃（下層ペロブスカイト非損傷）"}],"references":["ETH Zurich / Empa, Nature 642:592–598 (2025, PMC12176651) — Transparent Electrode Optical Loss Analysis","Panasonic Holdings (2023-03-17) — Organic Thin-Film Sensor Top Transparent Bias Electrode Structure"],"mirai":{"fhId":"FH02","volume":1,"badge":"超知能加速","eta":"2028 Q2〜2028 Q4","score":86,"axes":[18,13,19,18,18],"scoreRationale":"ベイヤー配列撤廃＋Foveon超えの急峻な色分離という構造優位性（19点）と物理突破（18点）は圧巻。一方、透明電極ロス（光利用率200〜250%級が物理上限）、現行試作の暗電流5桁ギャップ、鉛フリー化、PVD多層微細ビアの量産難度を厳格に見積もり量産民主化13点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"白色光・実効光利用率","current2026":"約25〜28%（CFで2/3吸収廃棄）","future2028":"実証47〜53%→目標60〜75%（実効2.0〜2.8倍・+1〜1.5段）"},{"metric":"色分離・偽色・モアレ","current2026":"デモザイク補間必須・偽色/モアレ発生","future2028":"1画素で完全RGB取得・Foveon比で極めて高い色純度"},{"metric":"光電変換と回路の構造","current2026":"PDと回路が面積を奪い合う","future2028":"薄膜光電変換層とCMOS回路が完全独立積層（GS容易）"},{"metric":"暗電流・環境規制ハードル","current2026":"室温0.02〜0.05 e-/s/pix・完全無毒Si","future2028":"現行試作暗電流5桁高＆鉛使用→ASI鉛フリー・低暗電流化必須"}],"sourceUrls":[{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (1)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12176651/"},{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (2)","url":"https://ethz.ch/en/news-and-events/eth-news/news/2025/06/better-images-for-humans-and-computers.html"},{"label":"Panasonic Holdings 公式プレスリリース（2023年3月17日、単層OPF有機センサー＋カラーフィルターによる600 nm透過1%未満・120 dB同時HDR・グローバルシャッター基盤実証）","url":"https://news.panasonic.com/global/topics/13982"},{"label":"arXiv（2026年9月、\\"PeroMAS: A Multi-agent System of Perovskite Material Discovery\\" — マルチエージェントAIによるペロブスカイト材料設計の先行研究）","url":"https://arxiv.org/html/2602.13312v2"}],"beginnerTitle":"光を通しながら電気を流す「最上層の透明電極シート（ITO）」","beginnerSummary":"ペロブスカイト膜から電気信号を取り出すには上下を電極で挟む必要がありますが、上が普通の金属だと光を遮ってしまいます。そこで「電気を通すのに透明な特殊膜（ITO）」を極限まで薄く載せ、外周の銀色の枠で電気を均一に配ります。","beginnerPoints":["3階建てのセンサーには合計4〜6枚の透明電極が挟まるため、1枚ごとの透明度を上げることが明るさアップの生命線です。","3Dモデルの右手前が階段状にカットされているため、最上層の透明電極とその下の青・緑・赤の重なりが一目で見渡せます。","外周の銀色の枠（銀バスバー）が、画面の真ん中まで遅れなく均一に電圧を届けます。"],"beginnerCaution":"透明電極を何層も挟むため「光利用率300%」とはいかず、電極のわずかな光ロスを正直に差し引いた「現行ベイヤーの2.0〜2.8倍（実効60〜75%）」が物理的に誠実な目標値です。","glossaryIds":["003","004"]}},{"id":"mirai-fh02-blue-perovskite-layer","diagramType":"mirai_fh02_blue_perovskite_layer","order":20,"miraiSubView":2,"swatchColor":"#2563eb","groupKey":"fh02_rgb_stack","assembledPos":[0,3.06,0],"explodeOffset":[0,21.5,0],"edgeOpacity":0.22,"title":"FH02-04. 第1受光層：コバルト青（400〜500nm）広バンドギャップ・ペロブスカイト膜","subtitle":"Layer 1 (Top): Wide-Bandgap (~2.45 eV) PVD Co-Evaporated Blue-Selective Perovskite Film","category":"FH02 3層垂直RGB / 青波長選択・光電変換層","plainAnalogy":"エネルギーの高い「青い光（400〜500nm）」だけをピンポイントで電気に変え、緑と赤の光はそのまま真下へ透き通す青い宝石のような極薄膜です。","summary":"バンドギャップを約2.45 eV（吸収端約500 nm）に精密チューニングし、低温真空共蒸着（PVD）でモノリシック成膜した青色専用ペロブスカイト光電変換膜。青光を完全吸収して電気信号へ変換しつつ、500 nm超の緑・赤光を無損失透過します。","opticsAndPhysics":["ハロゲン組成（Br/Cl比）の原子レベル調整によりバンドギャップ E_g ≈ 2.45 eV を設計すると、400〜500 nmの青色光子のみを急峻な吸収端で捕獲し、500 nm超の緑・赤光子はエネルギー不足のため膜を素通りします。","シリコン深さ依存の従来方式（Foveon）は吸収曲線がなだらかで色混じり（Frobenius誤差0.56）が大きかったのに対し、ペロブスカイト直接遷移半導体は吸収端が極めて鋭く、誤差0.18という圧倒的な色分離精度を発揮します。","ETH Zurich / EmpaのNature 2025実証では青層EQE 53%（現行ベイヤーB画素の約2倍）を達成。2028年に向けASI材料探索による鉛フリー無毒組成（Sn/Bi/ダブルペロブスカイト系）への置換が進みます。"],"formula":{"expression":"λ_cutoff = h·c / E_g ≈ 1240 / 2.45 eV ≈ 506 nm  (Blue EQE = 53% → 65%+)","description":"約2.45 eVの急峻な直接遷移バンドギャップにより、青光だけを吸収し緑・赤光を透過させる光学フィルター不要の波長分離を実現します。"},"nextGenInnovation":"カラーフィルター無しで青光を2倍効率で捕獲し、同時に下の緑・赤層への光学窓として機能するPVD多結晶ペロブスカイト層。","specs":[{"label":"吸収波長帯","value":"400〜500 nm（青色選択・E_g ≈ 2.45 eV）"},{"label":"実測→目標EQE","value":"53%（Nature 2025実証）→ 65〜75%（2028目標）"},{"label":"成膜プロセス","value":"低温真空共蒸着（PVD：下層非再溶解）"},{"label":"色分離誤差","value":"Frobeniusノルム 0.18（Foveon 0.56比で圧勝）"}],"references":["ETH Zurich / Empa, Nature 642:592–598 (2025-06-18, PMC12176651) — Blue Layer EQE 53% & Steep Bandgap Cutoff","arXiv:2602.13312v2 (2026) — PeroMAS Multi-Agent AI for Lead-Free Perovskite Material Discovery"],"mirai":{"fhId":"FH02","volume":1,"badge":"超知能加速","eta":"2028 Q2〜2028 Q4","score":86,"axes":[18,13,19,18,18],"scoreRationale":"ベイヤー配列撤廃＋Foveon超えの急峻な色分離という構造優位性（19点）と物理突破（18点）は圧巻。一方、透明電極ロス（光利用率200〜250%級が物理上限）、現行試作の暗電流5桁ギャップ、鉛フリー化、PVD多層微細ビアの量産難度を厳格に見積もり量産民主化13点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"白色光・実効光利用率","current2026":"約25〜28%（CFで2/3吸収廃棄）","future2028":"実証47〜53%→目標60〜75%（実効2.0〜2.8倍・+1〜1.5段）"},{"metric":"色分離・偽色・モアレ","current2026":"デモザイク補間必須・偽色/モアレ発生","future2028":"1画素で完全RGB取得・Foveon比で極めて高い色純度"},{"metric":"光電変換と回路の構造","current2026":"PDと回路が面積を奪い合う","future2028":"薄膜光電変換層とCMOS回路が完全独立積層（GS容易）"},{"metric":"暗電流・環境規制ハードル","current2026":"室温0.02〜0.05 e-/s/pix・完全無毒Si","future2028":"現行試作暗電流5桁高＆鉛使用→ASI鉛フリー・低暗電流化必須"}],"sourceUrls":[{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (1)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12176651/"},{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (2)","url":"https://ethz.ch/en/news-and-events/eth-news/news/2025/06/better-images-for-humans-and-computers.html"},{"label":"Panasonic Holdings 公式プレスリリース（2023年3月17日、単層OPF有機センサー＋カラーフィルターによる600 nm透過1%未満・120 dB同時HDR・グローバルシャッター基盤実証）","url":"https://news.panasonic.com/global/topics/13982"},{"label":"arXiv（2026年9月、\\"PeroMAS: A Multi-agent System of Perovskite Material Discovery\\" — マルチエージェントAIによるペロブスカイト材料設計の先行研究）","url":"https://arxiv.org/html/2602.13312v2"}],"beginnerTitle":"青い光だけを受け止め緑と赤を通す「1階・青ペロブスカイト膜」","beginnerSummary":"3階建て光電膜の一番上にあるコバルトブルーの極薄膜です。エネルギーが一番強い「青い光」だけをピタッと吸収して電気に変え、緑と赤の光はまるで透明なガラスのようにそのまま下の層へ通します。","beginnerPoints":["今までのベイヤー配列では青専用のマスが4分の1しかありませんでしたが、この層は全面すべてで青色を受け止めます。","液体で塗ると下の層が溶けてしまうため、真空中で分子をふんわり積もらせる「真空共蒸着（PVD）」で作ります。","スイスETHのNature論文（2025年）で、すでに今のカメラの約2倍の青色感度（53%）と圧倒的な色分離が実証されています。"],"beginnerCaution":"2025年時点の実験品はまだ鉛を使った8×8画素の試作であり、2028年にカメラへ載せるにはAI（超知能）による「鉛フリー無毒化」と「暗ノイズの大幅低減」が必須です。","glossaryIds":["003","004","098","108"]}},{"id":"mirai-fh02-etl-htl-interlayer-1","diagramType":"mirai_fh02_etl_htl_interlayer_1","order":21,"miraiSubView":2,"swatchColor":"#94a3b8","groupKey":"fh02_rgb_stack","assembledPos":[0,2.52,0],"explodeOffset":[0,16.5,0],"edgeOpacity":0.16,"title":"FH02-05. 電荷輸送層（ETL/HTL）＆第1透明光学絶縁スペーサ","subtitle":"Charge-Selective ETL / HTL Transport Stack & Optical Isolation Spacer 1 (Blue/Green)","category":"FH02 3層垂直RGB / 層間電荷分離＆電気絶縁層","plainAnalogy":"青の層と緑の層の電気が混ざらないように完璧に仕切りながら、生まれた電子だけを迷わず出口へ導く極薄の交通整理シートです。","summary":"青色ペロブスカイト層と緑色ペロブスカイト層を電気的に完全分離する光学透明絶縁スペーサ、電子輸送層（ETL：SnO₂/C₆₀系）、および正孔輸送層（HTL：NiO_x/PTAA系）の多層ナノ界面ユニット。","opticsAndPhysics":["青層で生成された電子・正孔対が再結合して消える前に高速分離・抽出し、かつ下の緑層へ電気的クロストーク（漏れ電流）が流入しないよう絶縁スペーサで遮断します。","層間屈折率を n ≈ 1.7〜1.9 に精密マッチングさせることで、青層と緑層の界面で起きるフレネル反射（光学干渉リップル）を極小化します。","電子ブロッキング障壁のエネルギー準位をASI計算化学で最適化することが、暗電流の5桁低減に直結します。"],"formula":{"expression":"J_dark ∝ exp(-Φ_barrier / k_B T)  |  R_int = ((n_1 - n_2)/(n_1 + n_2))^2","description":"高い注入障壁Φ_barrierによる暗電流抑止と、屈折率整合による層間反射損失極小化を同時に設計します。"},"nextGenInnovation":"光学透明絶縁と高速キャリア選択抽出を数ナノメートル厚で両立する垂直積層インターフェース。","specs":[{"label":"構成層","value":"ETL（電子輸送）＋ 透明絶縁スペーサ ＋ HTL（正孔輸送）"},{"label":"光透過率（>500nm）","value":"≥ 96%（緑・赤光を無損失透過）"},{"label":"層間電気クロストーク","value":"< 0.05%（完全独立読出し）"},{"label":"成膜手法","value":"真空蒸着＋ALD低温低温一括プロセス"}],"references":["ETH Zurich / Empa, Nature 642:592–598 (2025) — Monolithic Interlayer Spacer & Carrier Selective Contacts","Nature Electronics — Low-Dark-Current Charge Blocking Interlayers for Perovskite Photodiodes"],"mirai":{"fhId":"FH02","volume":1,"badge":"超知能加速","eta":"2028 Q2〜2028 Q4","score":86,"axes":[18,13,19,18,18],"scoreRationale":"ベイヤー配列撤廃＋Foveon超えの急峻な色分離という構造優位性（19点）と物理突破（18点）は圧巻。一方、透明電極ロス（光利用率200〜250%級が物理上限）、現行試作の暗電流5桁ギャップ、鉛フリー化、PVD多層微細ビアの量産難度を厳格に見積もり量産民主化13点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"白色光・実効光利用率","current2026":"約25〜28%（CFで2/3吸収廃棄）","future2028":"実証47〜53%→目標60〜75%（実効2.0〜2.8倍・+1〜1.5段）"},{"metric":"色分離・偽色・モアレ","current2026":"デモザイク補間必須・偽色/モアレ発生","future2028":"1画素で完全RGB取得・Foveon比で極めて高い色純度"},{"metric":"光電変換と回路の構造","current2026":"PDと回路が面積を奪い合う","future2028":"薄膜光電変換層とCMOS回路が完全独立積層（GS容易）"},{"metric":"暗電流・環境規制ハードル","current2026":"室温0.02〜0.05 e-/s/pix・完全無毒Si","future2028":"現行試作暗電流5桁高＆鉛使用→ASI鉛フリー・低暗電流化必須"}],"sourceUrls":[{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (1)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12176651/"},{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (2)","url":"https://ethz.ch/en/news-and-events/eth-news/news/2025/06/better-images-for-humans-and-computers.html"},{"label":"Panasonic Holdings 公式プレスリリース（2023年3月17日、単層OPF有機センサー＋カラーフィルターによる600 nm透過1%未満・120 dB同時HDR・グローバルシャッター基盤実証）","url":"https://news.panasonic.com/global/topics/13982"},{"label":"arXiv（2026年9月、\\"PeroMAS: A Multi-agent System of Perovskite Material Discovery\\" — マルチエージェントAIによるペロブスカイト材料設計の先行研究）","url":"https://arxiv.org/html/2602.13312v2"}],"beginnerTitle":"青と緑の電気が混ざるのを防ぐ「極薄・透明仕切りシート（第1層間）」","beginnerSummary":"青の膜と緑の膜をただ重ねただけでは電気が混ざって色が濁ってしまいます。そこで間に、緑と赤の光はスッと通しつつ電気だけはビシッと分けるナノレベルの透明シートを挟んでいます。","beginnerPoints":["青の層で生まれた電気信号だけを迷わず取り出し、隣の緑の層と絶対に混線させません。","光が境目で跳ね返って暗くならないよう、屈折率を合わせた滑らかな光学設計になっています。","暗い場所で勝手に電気が漏れる「暗電流」を食い止める、重要な逆流防止バルブの役割も担います。"],"beginnerCaution":"層間シートの欠陥やわずかなピンホールがそのまま暗ノイズに直結するため、原子レベルで均一な成膜管理が求められます。","glossaryIds":["004","008","108"]}},{"id":"mirai-fh02-green-perovskite-layer","diagramType":"mirai_fh02_green_perovskite_layer","order":22,"miraiSubView":2,"swatchColor":"#059669","groupKey":"fh02_rgb_stack","assembledPos":[0,1.96,0],"explodeOffset":[0,11.5,0],"edgeOpacity":0.22,"title":"FH02-06. 第2受光層：エメラルド緑（500〜600nm）ペロブスカイト／OPF膜","subtitle":"Layer 2 (Middle): Bandgap-Tuned (~2.05 eV) Green-Selective Perovskite / OPF Absorber","category":"FH02 3層垂直RGB / 緑波長選択・高解像輝度層","plainAnalogy":"青の層をすり抜けてきた光の中から「緑の光（500〜600nm）」だけを余さず捕らえ、赤い光だけを真下へ通すエメラルド色の薄膜です。","summary":"バンドギャップ約2.05 eV（吸収帯500〜600 nm）に設計された中層緑色選択ペロブスカイトまたは高吸光有機光電変換膜（OPF）。人間の視覚輝度感度の中心である緑チャンネルを全画素100%面積で取得します。","opticsAndPhysics":["上層の青膜が400〜500 nmを吸収済みのため、中層は500〜600 nmの緑色帯を急峻に吸収し、600 nm超の赤色光を下層へ透過させます。","ベイヤー配列ではG画素は全面積の50%ですが、FH02では全画素の100%で緑を受光（Nature 2025実証EQE 47%、目標60〜75%）。輝度MTFがナイキスト限界まで落ちません。","パナソニックが2023年に実証した高吸光有機薄膜（OPF）のCMOS回路分離グローバルシャッター知見とも親和性が高く、ハイブリッド構成（OPF＋ペロブスカイト）も有力選択肢です。"],"formula":{"expression":"λ_G ∈ [500, 600] nm (E_g ≈ 2.05 eV)  |  Spatial Fill = 100% (vs Bayer 50%)","description":"全画素100%の空間充填率で緑色輝度を取得し、デモザイク補間劣化のない真のネイティブ解像度を実現します。"},"nextGenInnovation":"全画素100%面積の緑受光により、同じ画素数でもベイヤー機を大幅に上回る圧倒的な実効解像感と滑らかな階調を達成。","specs":[{"label":"吸収波長帯","value":"500〜600 nm（緑色選択・E_g ≈ 2.05 eV）"},{"label":"実測→目標EQE","value":"47%（Nature 2025実証）→ 60〜75%（2028目標）"},{"label":"微細ビア貫通","value":"青層用垂直ビア絶縁パススルーカラー内蔵"},{"label":"先行量産基盤","value":"PVD共蒸着ペロブスカイト／OPF有機薄膜統合技術"}],"references":["ETH Zurich / Empa, Nature 642:592–598 (2025, PMC12176651) — Green Channel EQE 47% Monolithic Stack","Panasonic Holdings (2023-03-17) — Organic Photoconductive Film (OPF) 120 dB Global Shutter CMOS Platform"],"mirai":{"fhId":"FH02","volume":1,"badge":"超知能加速","eta":"2028 Q2〜2028 Q4","score":86,"axes":[18,13,19,18,18],"scoreRationale":"ベイヤー配列撤廃＋Foveon超えの急峻な色分離という構造優位性（19点）と物理突破（18点）は圧巻。一方、透明電極ロス（光利用率200〜250%級が物理上限）、現行試作の暗電流5桁ギャップ、鉛フリー化、PVD多層微細ビアの量産難度を厳格に見積もり量産民主化13点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"白色光・実効光利用率","current2026":"約25〜28%（CFで2/3吸収廃棄）","future2028":"実証47〜53%→目標60〜75%（実効2.0〜2.8倍・+1〜1.5段）"},{"metric":"色分離・偽色・モアレ","current2026":"デモザイク補間必須・偽色/モアレ発生","future2028":"1画素で完全RGB取得・Foveon比で極めて高い色純度"},{"metric":"光電変換と回路の構造","current2026":"PDと回路が面積を奪い合う","future2028":"薄膜光電変換層とCMOS回路が完全独立積層（GS容易）"},{"metric":"暗電流・環境規制ハードル","current2026":"室温0.02〜0.05 e-/s/pix・完全無毒Si","future2028":"現行試作暗電流5桁高＆鉛使用→ASI鉛フリー・低暗電流化必須"}],"sourceUrls":[{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (1)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12176651/"},{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (2)","url":"https://ethz.ch/en/news-and-events/eth-news/news/2025/06/better-images-for-humans-and-computers.html"},{"label":"Panasonic Holdings 公式プレスリリース（2023年3月17日、単層OPF有機センサー＋カラーフィルターによる600 nm透過1%未満・120 dB同時HDR・グローバルシャッター基盤実証）","url":"https://news.panasonic.com/global/topics/13982"},{"label":"arXiv（2026年9月、\\"PeroMAS: A Multi-agent System of Perovskite Material Discovery\\" — マルチエージェントAIによるペロブスカイト材料設計の先行研究）","url":"https://arxiv.org/html/2602.13312v2"}],"beginnerTitle":"人間の目に一番大事な緑を全画素で捉える「2階・緑ペロブスカイト膜」","beginnerSummary":"1階の青膜をすり抜けてきた光のうち、「緑の光」だけをしっかり吸収して電気に変え、赤い光だけを3階へ通すエメラルドグリーンの膜です。人間の目が明るさやクッキリ感を最も強く感じる緑を全画素100%で受け止めます。","beginnerPoints":["同じ画素数でも森の葉っぱや建物の細かい輪郭がハッとするほど緻密に写り、計算による補間（デモザイク）が要りません。","3Dモデルの階段カット断面では、コバルト青の下から顔を出す鮮やかなエメラルド緑のステップとして観察できます。","膜の表面には、上層の青信号を真下へ通すための極小の絶縁トンネル口（ビアカラー）が並んでいます。"],"beginnerCaution":"青層の信号を運ぶ極細の柱がこの緑の膜を通り抜けるため、通り道で電気がショートしない精密な絶縁加工（微細ビア技術）が量産の難関です。","glossaryIds":["003","004","101","111"]}},{"id":"mirai-fh02-etl-htl-interlayer-2","diagramType":"mirai_fh02_etl_htl_interlayer_2","order":23,"miraiSubView":2,"swatchColor":"#64748b","groupKey":"fh02_rgb_stack","assembledPos":[0,1.4,0],"explodeOffset":[0,6.5,0],"edgeOpacity":0.16,"title":"FH02-07. 第2層間ETL/HTL＆中層ITO読出し電極グリッド","subtitle":"Interlayer 2 ETL/HTL Charge-Transport & Mid-Stack Transparent ITO Readout Grid","category":"FH02 3層垂直RGB / 緑・赤層間透明電極＆分離膜","plainAnalogy":"緑の膜から電気を集めながら、一番下の赤の膜へ届く赤い光を遮らないように作られた、超透明な中2階の電極メッシュです。","summary":"緑色受光層と赤色受光層の間に配置される第2電荷輸送層（ETL/HTL）および中層透明ITO電極グリッド。緑チャンネルの高速電荷抽出と、600〜700 nm赤色光の無損失下方透過を両立します。","opticsAndPhysics":["中層ITOは上層の青層・緑層を通過した後の赤色光（600〜700 nm）を透過させる必要があるため、近赤外プラズマ吸収の少ない低キャリア濃度IZO／グラフェン複合透明電極が採用されます。","銀マイクロコレクター補助ラインがピクセル境界（非開口部）に沿って配置され、大判フルサイズ全面で緑・赤両チャンネルの同時グローバルシャッター高速リセットを保証します。"],"formula":{"expression":"T_mid(600–700 nm) ≥ 94%  &  τ_RC = R_sheet · C_pix < 50 ns","description":"赤色光の透過率94%以上と50 ns未満の超高速電荷読出し時定数を同時に満たします。"},"nextGenInnovation":"3層すべてをマイクロ秒未満で同時露光・同時リセットできる低RC中層透明電極アーキテクチャ。","specs":[{"label":"透明電極材","value":"低赤外吸収 IZO / ITO 透明導電グリッド"},{"label":"赤帯透過率","value":"≥ 94%（600〜700 nm）"},{"label":"電荷読出し時定数","value":"< 50 ns（グローバルシャッター対応）"},{"label":"電気絶縁耐圧","value":"緑/赤層間独立バイアス対応"}],"references":["ETH Zurich / Empa, Nature 642:592–598 (2025) — Mid-Stack Transparent Contact Engineering","Panasonic OPF Organic Sensor High-Speed Global Shutter Charge Extraction Architecture"],"mirai":{"fhId":"FH02","volume":1,"badge":"超知能加速","eta":"2028 Q2〜2028 Q4","score":86,"axes":[18,13,19,18,18],"scoreRationale":"ベイヤー配列撤廃＋Foveon超えの急峻な色分離という構造優位性（19点）と物理突破（18点）は圧巻。一方、透明電極ロス（光利用率200〜250%級が物理上限）、現行試作の暗電流5桁ギャップ、鉛フリー化、PVD多層微細ビアの量産難度を厳格に見積もり量産民主化13点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"白色光・実効光利用率","current2026":"約25〜28%（CFで2/3吸収廃棄）","future2028":"実証47〜53%→目標60〜75%（実効2.0〜2.8倍・+1〜1.5段）"},{"metric":"色分離・偽色・モアレ","current2026":"デモザイク補間必須・偽色/モアレ発生","future2028":"1画素で完全RGB取得・Foveon比で極めて高い色純度"},{"metric":"光電変換と回路の構造","current2026":"PDと回路が面積を奪い合う","future2028":"薄膜光電変換層とCMOS回路が完全独立積層（GS容易）"},{"metric":"暗電流・環境規制ハードル","current2026":"室温0.02〜0.05 e-/s/pix・完全無毒Si","future2028":"現行試作暗電流5桁高＆鉛使用→ASI鉛フリー・低暗電流化必須"}],"sourceUrls":[{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (1)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12176651/"},{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (2)","url":"https://ethz.ch/en/news-and-events/eth-news/news/2025/06/better-images-for-humans-and-computers.html"},{"label":"Panasonic Holdings 公式プレスリリース（2023年3月17日、単層OPF有機センサー＋カラーフィルターによる600 nm透過1%未満・120 dB同時HDR・グローバルシャッター基盤実証）","url":"https://news.panasonic.com/global/topics/13982"},{"label":"arXiv（2026年9月、\\"PeroMAS: A Multi-agent System of Perovskite Material Discovery\\" — マルチエージェントAIによるペロブスカイト材料設計の先行研究）","url":"https://arxiv.org/html/2602.13312v2"}],"beginnerTitle":"緑の電気を集め赤の光を通す「中2階の透明電極メッシュ」","beginnerSummary":"2階の緑の膜と3階の赤の膜の間に挟まれた、2枚目の透明電極と仕切り膜です。緑の層が生んだ電気を素早く集めながら、残り3分の1の「赤い光」を邪魔せず一番下まで送り届けます。","beginnerPoints":["赤い光が透明電極に吸い込まれて暗くならないよう、赤い光に特別に透明な配合（IZO/ITO）を使っています。","ピクセルのスキマに沿った極細の銀ラインが電気の流れを助け、動く被写体が歪まないグローバルシャッター動作を支えます。","この層があるおかげで、緑と赤の信号が一切混ざらず完全に独立して読み出されます。"],"beginnerCaution":"透明電極を増やすほど少しずつ光が減るため、いかに薄く透明かつ電気抵抗を低く保てるかが物理的な腕の見せどころです。","glossaryIds":["004","008"]}},{"id":"mirai-fh02-red-perovskite-layer","diagramType":"mirai_fh02_red_perovskite_layer","order":24,"miraiSubView":2,"swatchColor":"#dc2626","groupKey":"fh02_rgb_stack","assembledPos":[0,0.82,0],"explodeOffset":[0,1.8,0],"edgeOpacity":0.22,"title":"FH02-08. 第3受光層：ルビー赤（600〜700nm）狭バンドギャップ・ペロブスカイト膜","subtitle":"Layer 3 (Bottom): Narrow-Bandgap (~1.72 eV) Red-Selective Perovskite Absorber Film","category":"FH02 3層垂直RGB / 赤波長選択・底面吸収層","plainAnalogy":"青と緑の層をくぐり抜けてきた「赤い光（600〜700nm）」を残らずキャッチして電気に変える、3階建て最下層のルビー色の光電膜です。","summary":"バンドギャップ約1.72 eV（吸収端約720 nm）に設計され、36×24 mm全面に成膜された最下層ルビー赤色ペロブスカイト光電変換膜。青・緑層を透過した600〜700 nmの赤色光を全画素100%面積で高効率吸収します。","opticsAndPhysics":["従来のベイヤー配列では赤画素は4画素中わずか1画素（25%）しかなく、赤い花びらや夕焼け、肌色の微細テクスチャがデモザイク補間で最も解像低下しやすい弱点でした。","FH02の最下層赤ペロブスカイト膜は全面積100%で赤色光を受け止め（Nature 2025実証EQE 50%＝現行ベイヤーR画素の2倍超）、かつ下面タングステン反射電極によるダブルパス吸収で長波長赤光の取りこぼしを防ぎます。","約720 nm超の近赤外光を自然に透過・カットする急峻バンドギャップにより、従来より薄型のIRカット構成で深い赤と正確な肌色（固有色科学）を再現します。"],"formula":{"expression":"λ_R ∈ [600, 700] nm (E_g ≈ 1.72 eV)  |  Red EQE = 50% (Nature 2025) → 65%+ (2028)","description":"全画素100%の赤色受光と底面電極のダブルパス反射により、ベイヤー比で赤チャンネルの解像度と感度を同時倍増させます。"},"nextGenInnovation":"ベイヤー配列最大の弱点だった赤チャンネル（25%面積）を100%フル解像度へ解放する狭バンドギャップ垂直吸収層。","specs":[{"label":"吸収波長帯","value":"600〜700 nm（赤色選択・E_g ≈ 1.72 eV）"},{"label":"実測→目標EQE","value":"50%（Nature 2025実証）→ 65〜75%（2028目標）"},{"label":"底面反射回収","value":"タングステン反射コレクターによるダブルパス吸収"},{"label":"赤色MTF改善","value":"ベイヤー25%配置比で実質約2×の空間サンプリング密度"}],"references":["ETH Zurich / Empa, Nature 642:592–598 (2025, PMC12176651) — Red Layer EQE 50% & Full-Color Reconstruction","arXiv:2602.13312v2 (2026) — PeroMAS AI Discovery of Stable Narrow-Bandgap Lead-Free Perovskites"],"mirai":{"fhId":"FH02","volume":1,"badge":"超知能加速","eta":"2028 Q2〜2028 Q4","score":86,"axes":[18,13,19,18,18],"scoreRationale":"ベイヤー配列撤廃＋Foveon超えの急峻な色分離という構造優位性（19点）と物理突破（18点）は圧巻。一方、透明電極ロス（光利用率200〜250%級が物理上限）、現行試作の暗電流5桁ギャップ、鉛フリー化、PVD多層微細ビアの量産難度を厳格に見積もり量産民主化13点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"白色光・実効光利用率","current2026":"約25〜28%（CFで2/3吸収廃棄）","future2028":"実証47〜53%→目標60〜75%（実効2.0〜2.8倍・+1〜1.5段）"},{"metric":"色分離・偽色・モアレ","current2026":"デモザイク補間必須・偽色/モアレ発生","future2028":"1画素で完全RGB取得・Foveon比で極めて高い色純度"},{"metric":"光電変換と回路の構造","current2026":"PDと回路が面積を奪い合う","future2028":"薄膜光電変換層とCMOS回路が完全独立積層（GS容易）"},{"metric":"暗電流・環境規制ハードル","current2026":"室温0.02〜0.05 e-/s/pix・完全無毒Si","future2028":"現行試作暗電流5桁高＆鉛使用→ASI鉛フリー・低暗電流化必須"}],"sourceUrls":[{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (1)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12176651/"},{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (2)","url":"https://ethz.ch/en/news-and-events/eth-news/news/2025/06/better-images-for-humans-and-computers.html"},{"label":"Panasonic Holdings 公式プレスリリース（2023年3月17日、単層OPF有機センサー＋カラーフィルターによる600 nm透過1%未満・120 dB同時HDR・グローバルシャッター基盤実証）","url":"https://news.panasonic.com/global/topics/13982"},{"label":"arXiv（2026年9月、\\"PeroMAS: A Multi-agent System of Perovskite Material Discovery\\" — マルチエージェントAIによるペロブスカイト材料設計の先行研究）","url":"https://arxiv.org/html/2602.13312v2"}],"beginnerTitle":"赤い花びらや夕焼けを100%捉える「3階・赤ペロブスカイト膜」","beginnerSummary":"青と緑の膜をくぐり抜けて届いた「赤い光」を残さずキャッチする、一番下のルビー色の膜です。今のカメラでは赤担当のマスが全体の4分の1しかありませんが、FH02では画面の100%全面で赤を受け止めます。","beginnerPoints":["赤いバラの花びら、夕焼けのグラデーション、人物の繊細な肌色が、塗りつぶれず驚くほど立体的に写ります。","3Dモデルの階段カットのいちばん広い底面として輝くルビーレッドの層が、この第3受光膜です。","底面の金属電極が通り抜けかけた赤い光をもう一度跳ね返して吸い込む（ダブルパス吸収）ため、ムダがありません。"],"beginnerCaution":"狭バンドギャップの赤層は熱エネルギーで電子が飛び出しやすく（暗電流の原因）、次のパッシベーション膜とAI材料設計による低暗ノイズ化が最大の勝負所です。","glossaryIds":["003","004","008","111"]}},{"id":"mirai-fh02-vertical-via-pillars","diagramType":"mirai_fh02_vertical_via_pillars","order":25,"miraiSubView":2,"swatchColor":"#d97706","groupKey":"fh02_rgb_stack","assembledPos":[0,0.02,0],"explodeOffset":[22,12,14],"edgeOpacity":0.18,"title":"FH02-09. 3段階スタッガード垂直RGBマイクロビア柱アレイ","subtitle":"3-Height Staggered Vertical Tungsten/Copper RGB Micro-Via Interconnect Pillars","category":"FH02 3層垂直RGB / 3色独立・垂直立体配線柱","plainAnalogy":"1階（青）・2階（緑）・3階（赤）それぞれのフロアから、地下の読み出しチップへ3色の電気を別々のエレベーターで直通させる3段階の高さの金属柱です。","summary":"各画素セルごとに「短（赤層直結）・中（緑層直結）・長（青層直結）」の3つの異なる高さを備えたタングステン／銅垂直マイクロビア柱アレイ。3層垂直積層で生成されたRGB 3チャンネルの電荷を、完全に独立したまま直下のCMOS ROICへ同時伝送します。","opticsAndPhysics":["2025年のNature実証（8×8×3画素）をフルサイズ2,400万〜4,500万画素（画素ピッチ2〜4 μm級）へ微細化する上で最大の構造障壁が、3つの異なる深さの層から互いに短絡せず信号を取り出す3D垂直ビア形成です。","高アスペクト比エッチング＋ALD側壁絶縁ライナー＋タングステン/銅埋め込みにより、1画素内の極小フットプリント（<8%面積）へ3本の高さ別マイクロビアを千鳥配置（スタッガード）します。","ビア先端の金マイクロカラーが各層電極と低接触抵抗オーム接続を形成し、RGB 3色の同時並列読み出しを成立させます。"],"formula":{"expression":"A_via_loss = 3 · π r_via^2 / p_pix^2 < 6%  (r_via ≈ 180 nm, p_pix = 3.6 μm)","description":"サブミクロン級3高さ垂直ビアの微細加工により、受光面積損失を6%未満に抑えながら3色完全独立読み出しを実現します。"},"nextGenInnovation":"3D半導体BEOL微細ビア技術を3層光電変換膜へ融合させた、フルサイズ3層垂直RGB量産化の核心構造。","specs":[{"label":"ビア構造","value":"短（赤）・中（緑）・長（青）3段階高さスタッガード柱"},{"label":"導体・絶縁","value":"タングステン／銅コア ＋ ALD Al₂O₃側壁絶縁ライナー"},{"label":"占有面積損失","value":"< 6% / 画素（3本合計）"},{"label":"接続方式","value":"3チャンネル同時・直下ROIC着地パッド直結"}],"references":["ETH Zurich / Empa, Nature 642:592–598 (2025) — Vertical Pixel Interconnect Scaling Roadmap","imec 300mm Thin-Film Photodetector Monolithic Back-End-of-Line (BEOL) Micro-Via Integration"],"mirai":{"fhId":"FH02","volume":1,"badge":"超知能加速","eta":"2028 Q2〜2028 Q4","score":86,"axes":[18,13,19,18,18],"scoreRationale":"ベイヤー配列撤廃＋Foveon超えの急峻な色分離という構造優位性（19点）と物理突破（18点）は圧巻。一方、透明電極ロス（光利用率200〜250%級が物理上限）、現行試作の暗電流5桁ギャップ、鉛フリー化、PVD多層微細ビアの量産難度を厳格に見積もり量産民主化13点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"白色光・実効光利用率","current2026":"約25〜28%（CFで2/3吸収廃棄）","future2028":"実証47〜53%→目標60〜75%（実効2.0〜2.8倍・+1〜1.5段）"},{"metric":"色分離・偽色・モアレ","current2026":"デモザイク補間必須・偽色/モアレ発生","future2028":"1画素で完全RGB取得・Foveon比で極めて高い色純度"},{"metric":"光電変換と回路の構造","current2026":"PDと回路が面積を奪い合う","future2028":"薄膜光電変換層とCMOS回路が完全独立積層（GS容易）"},{"metric":"暗電流・環境規制ハードル","current2026":"室温0.02〜0.05 e-/s/pix・完全無毒Si","future2028":"現行試作暗電流5桁高＆鉛使用→ASI鉛フリー・低暗電流化必須"}],"sourceUrls":[{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (1)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12176651/"},{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (2)","url":"https://ethz.ch/en/news-and-events/eth-news/news/2025/06/better-images-for-humans-and-computers.html"},{"label":"Panasonic Holdings 公式プレスリリース（2023年3月17日、単層OPF有機センサー＋カラーフィルターによる600 nm透過1%未満・120 dB同時HDR・グローバルシャッター基盤実証）","url":"https://news.panasonic.com/global/topics/13982"},{"label":"arXiv（2026年9月、\\"PeroMAS: A Multi-agent System of Perovskite Material Discovery\\" — マルチエージェントAIによるペロブスカイト材料設計の先行研究）","url":"https://arxiv.org/html/2602.13312v2"}],"beginnerTitle":"青・緑・赤を別々に地下へ届ける「3段階エレベーター柱（垂直ビア）」","beginnerSummary":"3階建ての青・緑・赤の膜から、どうやって3色の電気を混ぜずに下のチップへ下ろすのか？ その答えが、高さの違う「長い柱（青用）」「中くらいの柱（緑用）」「短い柱（赤用）」を1マスごとに3本並べる立体エレベーター配線です。","beginnerPoints":["3Dモデルの分解スライダーを動かすと、この3段階の高さの銅・タングステン柱の森が右斜め前へスライドしてくっきり見えます。","柱の側面は極薄の絶縁コートで覆われているため、長い青用の柱が緑や赤の膜を突き抜けても絶対にショートしません。","3本の柱がすべて同時に電気を下へ運ぶため、1回のシャッターで赤・緑・青のズレがゼロの完全な色データが手に入ります。"],"beginnerCaution":"2〜4ミクロンの極小画素の中に高さの違う3本の柱を何千万セットも不良なく立てる加工は極めて難しく、2028年の量産スコア（13/20点）を抑えた主要因の一つです。","glossaryIds":["004","101","106"]}},{"id":"mirai-fh02-passivation-darkblock","diagramType":"mirai_fh02_passivation_darkblock","order":26,"miraiSubView":2,"swatchColor":"#7c3aed","groupKey":"fh02_roic","assembledPos":[0,0.26,0],"explodeOffset":[0,-3.5,0],"edgeOpacity":0.18,"title":"FH02-10. 粒界パッシベーション＆暗電流ブロッキング・ナノ膜","subtitle":"ASI-Designed Grain-Boundary Passivation & Dark-Current Electron-Blocking Nano-Film","category":"FH02 3層垂直RGB / 暗電流5桁低減ブレイクスルー層","plainAnalogy":"ペロブスカイト結晶のスキマから暗闇で勝手に漏れ出す電気ノイズを、AIが設計した魔法の極薄分子膜で5桁（10万分の1）に封じ込める核心層です。","summary":"多結晶ペロブスカイト膜の粒界欠陥（トラップ準位）を分子終端し、ROIC電極からの熱電子注入（暗電流）を阻止するASI設計パッシベーション＆電子ブロッキングナノ薄膜。現行試作とカメラ実用の間にある暗電流5桁ギャップを埋める最重要層です。","opticsAndPhysics":["Nature 2025試作ペロブスカイト素子の暗電流密度は10〜50 nA/cm²（4 μm角画素換算で毎秒数万電子）であり、現行Si-CMOS（室温0.02〜0.05 e-/s/pix）に対して約5桁の巨大な隔たりが存在します。","2027〜2028年のASI自律材料探索（PeroMAS系＋自律ロボット実験室）が見出した双性イオン分子・極薄High-K Al₂O₃トンネル障壁・粒界パッシベーションにより、表面再結合と熱キャリア注入を劇的に抑制します。","外周の金ガードリングがチップ端面のリーク電流をバイパス排出し、長秒露光時の端かぶり（アンプグロー類似現象）を防止します。"],"formula":{"expression":"J_dark: 10–50 nA/cm^2 (2025) → < 10^-3 nA/cm^2 (2028 ASI Target, -5 orders)","description":"暗電流密度の5桁低減が、ペロブスカイト3層センサーを「明るい実験室試作」から「暗所カメラ実用機」へ昇華させる絶対条件です。"},"nextGenInnovation":"超知能（ASI）＋自律ロボット実験室（Self-Driving Labs）が導く分子粒界パッシベーションによる暗電流5桁突破。","specs":[{"label":"機能役割","value":"多結晶粒界トラップ終端＋熱電子注入ブロッキング"},{"label":"暗電流低減目標","value":"2025試作比 約10⁻⁵倍（5桁低減・静止画暗所実用域）"},{"label":"材料設計手法","value":"ASI自律材料探索（PeroMAS発展系）× 自律実験室"},{"label":"エッジ保護","value":"全周金ガードリング（端面リーク排出）"}],"references":["ETH Zurich / Empa, Nature 642:592–598 (2025, PMC12176651) — Dark Current Density Baseline (10–50 nA/cm^2)","arXiv:2602.13312v2 (2026) — PeroMAS Multi-Agent AI for Perovskite Defect Passivation Discovery"],"mirai":{"fhId":"FH02","volume":1,"badge":"超知能加速","eta":"2028 Q2〜2028 Q4","score":86,"axes":[18,13,19,18,18],"scoreRationale":"ベイヤー配列撤廃＋Foveon超えの急峻な色分離という構造優位性（19点）と物理突破（18点）は圧巻。一方、透明電極ロス（光利用率200〜250%級が物理上限）、現行試作の暗電流5桁ギャップ、鉛フリー化、PVD多層微細ビアの量産難度を厳格に見積もり量産民主化13点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"白色光・実効光利用率","current2026":"約25〜28%（CFで2/3吸収廃棄）","future2028":"実証47〜53%→目標60〜75%（実効2.0〜2.8倍・+1〜1.5段）"},{"metric":"色分離・偽色・モアレ","current2026":"デモザイク補間必須・偽色/モアレ発生","future2028":"1画素で完全RGB取得・Foveon比で極めて高い色純度"},{"metric":"光電変換と回路の構造","current2026":"PDと回路が面積を奪い合う","future2028":"薄膜光電変換層とCMOS回路が完全独立積層（GS容易）"},{"metric":"暗電流・環境規制ハードル","current2026":"室温0.02〜0.05 e-/s/pix・完全無毒Si","future2028":"現行試作暗電流5桁高＆鉛使用→ASI鉛フリー・低暗電流化必須"}],"sourceUrls":[{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (1)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12176651/"},{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (2)","url":"https://ethz.ch/en/news-and-events/eth-news/news/2025/06/better-images-for-humans-and-computers.html"},{"label":"Panasonic Holdings 公式プレスリリース（2023年3月17日、単層OPF有機センサー＋カラーフィルターによる600 nm透過1%未満・120 dB同時HDR・グローバルシャッター基盤実証）","url":"https://news.panasonic.com/global/topics/13982"},{"label":"arXiv（2026年9月、\\"PeroMAS: A Multi-agent System of Perovskite Material Discovery\\" — マルチエージェントAIによるペロブスカイト材料設計の先行研究）","url":"https://arxiv.org/html/2602.13312v2"}],"beginnerTitle":"暗ノイズを10万分の1へ封じる「AI設計・漏れ止めナノ膜」","beginnerSummary":"2025年の実験品は光効率が素晴らしい一方、暗い場所で勝手に電気が漏れる「暗ノイズ」が今のシリコンの何万倍も大きいのが弱点でした。AI（超知能）が設計したこの紫色の極薄ナノ膜が、結晶のスキマをピタッと塞いで暗ノイズを劇的に減らします。","beginnerPoints":["結晶の粒と粒のスキマ（粒界）に潜む小さな傷を分子レベルで補修（パッシベーション）し、誤ノイズの発生源を潰します。","下の回路から熱で勝手に電子が逆流するのをブロックし、星や夜景の長秒撮影を実用レベルへ引き上げます。","この層の進化こそが、FH02が `[超知能加速]` に分類されている最大の理由です。"],"beginnerCaution":"5桁（10万分の1）もの暗電流低減は材料科学として非常に高いハードルであり、実現時期が2028年後半〜になる現実的な理由でもあります。","glossaryIds":["004","008","098","108"]}},{"id":"mirai-fh02-cmos-roic-wafer","diagramType":"mirai_fh02_cmos_roic_wafer","order":27,"miraiSubView":2,"swatchColor":"#1e40af","groupKey":"fh02_roic","assembledPos":[0,-0.3,0],"explodeOffset":[0,-8.5,0],"edgeOpacity":0.22,"title":"FH02-11. 300mm互換 3チャンネル同時RGB CMOS読出しウェーハ（ROIC）","subtitle":"300mm Foundry-Compatible 3-Channel Simultaneous RGB Global-Shutter CMOS ROIC Wafer","category":"FH02 3層垂直RGB / 3色並列グローバルシャッター読出し層","plainAnalogy":"光を受け止める仕事は上の3層膜に全部まかせ、シリコン面積の100%を使って赤・緑・青の3色信号を同時に高画質変換する専用読み出しチップです。","summary":"上層の3層垂直ペロブスカイト膜と完全に機能分離された300mmシリコンCMOS読み出し回路（ROIC）ウェーハ。各画素直下にB/G/R独立3チャンネルの蓄積ノード・グローバルシャッター容量・CDS回路、上下縁に16-bit並列カラムADCバンクを搭載します。","opticsAndPhysics":["従来のシリコンCISでは「光を受けるフォトダイオード」と「電気を扱うトランジスタ・蓄積容量」が同じシリコン平面の面積を奪い合っていました。","FH02では光電変換を全面上層の薄膜へ分離したため、シリコンROIC面積の100%を3チャンネル独立の巨大蓄積容量（高FWC＝広ダイナミックレンジ）と完全グローバルシャッター・低ノイズCDS回路へ投入できます。","パナソニックOPFセンサーの先行実証と同様、既存300mm Si-CMOSファブでROICを大量生産し、後工程（BEOL）で低温PVD成膜を載せることで量産民主化が成立します。"],"formula":{"expression":"FWC_3ch ∝ C_storage(100% Si Area)  |  Readout = 3 × Full-Frame Simultaneous 16-bit","description":"光電変換とシリコン回路の完全立体分離により、3色同時グローバルシャッターと極めて大きな飽和電荷量を両立します。"},"nextGenInnovation":"光電変換とシリコン回路の完全役割分担により、3層RGB同時グローバルシャッター＋16-bit並列読出しを既存300mm工場で実現。","specs":[{"label":"チップ構造","value":"300mm互換 3ch同時RGB CMOS ROIC（36.4×24.4 mm）"},{"label":"シャッター方式","value":"全画素・3色同時グローバルシャッター（歪みゼロ）"},{"label":"AD変換器","value":"上下対称 16-bit 3色並列カラムADCバンク"},{"label":"着地パッド","value":"画素あたり B / G / R 3独立マイクロビア着地端子"}],"references":["Panasonic Holdings (2023-03-17) — Separated Thin-Film Absorber & CMOS ROIC 120 dB Global Shutter","ETH Zurich / Empa, Nature 642:592–598 (2025) — Monolithic CMOS ROIC Integration Architecture"],"mirai":{"fhId":"FH02","volume":1,"badge":"超知能加速","eta":"2028 Q2〜2028 Q4","score":86,"axes":[18,13,19,18,18],"scoreRationale":"ベイヤー配列撤廃＋Foveon超えの急峻な色分離という構造優位性（19点）と物理突破（18点）は圧巻。一方、透明電極ロス（光利用率200〜250%級が物理上限）、現行試作の暗電流5桁ギャップ、鉛フリー化、PVD多層微細ビアの量産難度を厳格に見積もり量産民主化13点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"白色光・実効光利用率","current2026":"約25〜28%（CFで2/3吸収廃棄）","future2028":"実証47〜53%→目標60〜75%（実効2.0〜2.8倍・+1〜1.5段）"},{"metric":"色分離・偽色・モアレ","current2026":"デモザイク補間必須・偽色/モアレ発生","future2028":"1画素で完全RGB取得・Foveon比で極めて高い色純度"},{"metric":"光電変換と回路の構造","current2026":"PDと回路が面積を奪い合う","future2028":"薄膜光電変換層とCMOS回路が完全独立積層（GS容易）"},{"metric":"暗電流・環境規制ハードル","current2026":"室温0.02〜0.05 e-/s/pix・完全無毒Si","future2028":"現行試作暗電流5桁高＆鉛使用→ASI鉛フリー・低暗電流化必須"}],"sourceUrls":[{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (1)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12176651/"},{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (2)","url":"https://ethz.ch/en/news-and-events/eth-news/news/2025/06/better-images-for-humans-and-computers.html"},{"label":"Panasonic Holdings 公式プレスリリース（2023年3月17日、単層OPF有機センサー＋カラーフィルターによる600 nm透過1%未満・120 dB同時HDR・グローバルシャッター基盤実証）","url":"https://news.panasonic.com/global/topics/13982"},{"label":"arXiv（2026年9月、\\"PeroMAS: A Multi-agent System of Perovskite Material Discovery\\" — マルチエージェントAIによるペロブスカイト材料設計の先行研究）","url":"https://arxiv.org/html/2602.13312v2"}],"beginnerTitle":"3色の電気を同時に受け止める「専用シリコン読み出しチップ（ROIC）」","beginnerSummary":"今のセンサーは1枚のシリコン板の中で「光を受ける場所」と「電気を処理する回路」が場所を取り合っています。FH02では光を受ける仕事を上の3層膜へ任せたため、このシリコン板の100%すべてを贅沢な3色同時読み出し回路に使えます。","beginnerPoints":["青・緑・赤それぞれ専用の大きな電気貯蔵庫と16ビット変換器を積めるため、動体歪みゼロのグローバルシャッターと広い明暗幅を両立できます。","チップの上下に青・緑・赤で色分けされた高速ADC（デジタル変換器）が整然と並んでいる様子を3Dモデルで観察できます。","土台となるこのチップは普通の300mmシリコン工場で作れるため、将来の低価格化（民主化）にも大きく貢献します。"],"beginnerCaution":"1画素から3色（従来の3倍）のデータを同時読み出しするため、後段の配線本数や電力・データ処理帯域も3倍級に強化する必要があります。","glossaryIds":["003","004","009","012"]}},{"id":"mirai-fh02-color-matrix-dsp","diagramType":"mirai_fh02_color_matrix_dsp","order":28,"miraiSubView":2,"swatchColor":"#4338ca","groupKey":"fh02_roic","assembledPos":[0,-1.1,0],"explodeOffset":[0,-14,0],"edgeOpacity":0.22,"title":"FH02-12. 分光クロストーク補正カラーマトリクスDSP＆温度補償ダイ","subtitle":"On-Package Spectral-Crosstalk 3×3 Color-Matrix DSP & Thermal Bandgap Compensation Die","category":"FH02 3層垂直RGB / 固有色科学＆分光補正ロジック層","plainAnalogy":"温度でわずかに揺らぐペロブスカイトの色波長をリアルタイムで補正し、カメラメーカー独自の美しい色再現（固有色科学）へ整える色専用プロセッサです。","summary":"ROIC直下にCu-Cu接合された3×3シストリック・カラーマトリクス演算DSPダイ。ペロブスカイト層の温度依存バンドギャップシフトと微細な層間分光オーバーラップをリアルタイム物理補正し、高精度なCIE色空間出力を生成します。","opticsAndPhysics":["ペロブスカイト半導体は温度変化に対してわずかなバンドギャップ・シフト（dE_g/dT ≈ +0.2〜0.4 meV/K、シリコンと逆符号のVarshni挙動）を示すため、温度連動の動的3×3色補正行列が正確な色再現の鍵となります。","Foveon方式では強い色混じりを補正するため行列係数の非対角項が肥大化し暗所カラーノイズが増幅されましたが、FH02の急峻バンドギャップ分離（Frobenius 0.18）なら行列条件数が極めて小さく、ノイズ増幅無しで高純度発色を得られます。","3色同時データ（従来比3倍）をセンサー内DSPで即座に可逆圧縮・色空間整形し、カメラ本体のメインISP負荷を大幅に軽減します。"],"formula":{"expression":"[R_out, G_out, B_out]^T = M_3x3(T_die) · [I_R, I_G, I_B]^T  (cond(M) ≈ 1.3)","description":"急峻なバンドギャップ色分離により色補正行列の条件数が低く、Foveonの課題だった色ノイズ増幅を防ぎます。"},"nextGenInnovation":"温度連動ペロブスカイト分光補正×低条件数カラーマトリクス演算のセンサーパッケージ内リアルタイム実行。","specs":[{"label":"演算ユニット","value":"3×3 シストリック分光補正MACアレイ（16-bit浮動/固定）"},{"label":"色行列条件数","value":"cond(M) ≈ 1.3（Foveon比で色ノイズ増幅極小）"},{"label":"温度補償機能","value":"リアルタイム dE_g/dT バンドギャップ色補正"},{"label":"接合方式","value":"ROIC直下 Cu-Cuマイクロパッド直接積層"}],"references":["ETH Zurich / Empa, Nature 642:592–598 (2025, PMC12176651) — Colour Reconstruction Frobenius Norm 0.18 vs Foveon 0.56","CIE 1931 Colorimetric Matrix Transformation & Noise Propagation Condition Number Theory"],"mirai":{"fhId":"FH02","volume":1,"badge":"超知能加速","eta":"2028 Q2〜2028 Q4","score":86,"axes":[18,13,19,18,18],"scoreRationale":"ベイヤー配列撤廃＋Foveon超えの急峻な色分離という構造優位性（19点）と物理突破（18点）は圧巻。一方、透明電極ロス（光利用率200〜250%級が物理上限）、現行試作の暗電流5桁ギャップ、鉛フリー化、PVD多層微細ビアの量産難度を厳格に見積もり量産民主化13点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"白色光・実効光利用率","current2026":"約25〜28%（CFで2/3吸収廃棄）","future2028":"実証47〜53%→目標60〜75%（実効2.0〜2.8倍・+1〜1.5段）"},{"metric":"色分離・偽色・モアレ","current2026":"デモザイク補間必須・偽色/モアレ発生","future2028":"1画素で完全RGB取得・Foveon比で極めて高い色純度"},{"metric":"光電変換と回路の構造","current2026":"PDと回路が面積を奪い合う","future2028":"薄膜光電変換層とCMOS回路が完全独立積層（GS容易）"},{"metric":"暗電流・環境規制ハードル","current2026":"室温0.02〜0.05 e-/s/pix・完全無毒Si","future2028":"現行試作暗電流5桁高＆鉛使用→ASI鉛フリー・低暗電流化必須"}],"sourceUrls":[{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (1)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12176651/"},{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (2)","url":"https://ethz.ch/en/news-and-events/eth-news/news/2025/06/better-images-for-humans-and-computers.html"},{"label":"Panasonic Holdings 公式プレスリリース（2023年3月17日、単層OPF有機センサー＋カラーフィルターによる600 nm透過1%未満・120 dB同時HDR・グローバルシャッター基盤実証）","url":"https://news.panasonic.com/global/topics/13982"},{"label":"arXiv（2026年9月、\\"PeroMAS: A Multi-agent System of Perovskite Material Discovery\\" — マルチエージェントAIによるペロブスカイト材料設計の先行研究）","url":"https://arxiv.org/html/2602.13312v2"}],"beginnerTitle":"プロ級の美しい色を仕上げる「色専用ミニ頭脳（カラーDSP）」","beginnerSummary":"3層ペロブスカイトはFoveonよりずっとクッキリ色を分けられますが、気温によって吸収する波長がほんの少し動きます。ROICのすぐ下に重ねたこの小さな専用チップが、温度に合わせてリアルタイムで完璧な色へ微調整します。","beginnerPoints":["青・緑・赤が元から綺麗に分離しているため、色を補正するときに暗所のカラーノイズが暴れず、夜景でもクリアな色が保てます。","チップ表面に並ぶ3×3の小さなブロックが、画素ごとの色を瞬時に掛け算補正する専用計算エンジンです。","3倍になったRGBデータを賢く整えてからカメラ本体へ送り、連写速度の低下を防ぎます。"],"beginnerCaution":"ペロブスカイトは従来のシリコンとは温度による波長変化の向きが異なるため、各温度での工場キャリブレーション（LUT学習）が品質を左右します。","glossaryIds":["004","102","111"]}},{"id":"mirai-fh02-hermetic-ceramic-carrier","diagramType":"mirai_fh02_hermetic_ceramic_carrier","order":29,"miraiSubView":2,"swatchColor":"#475569","groupKey":"fh02_encapsulation","assembledPos":[0,-1.1,0],"explodeOffset":[0,-19.5,0],"edgeOpacity":0.24,"title":"FH02-13. N₂パージ完全気密セラミックキャリア＆コバール溶接フランジ","subtitle":"N2-Purged Hermetic Ceramic Carrier Cavity, Kovar Laser Seam-Weld Flange & LGA Array","category":"FH02 3層垂直RGB / 乾燥窒素封入・完全気密筐体","plainAnalogy":"センサー内部をカラカラの乾燥窒素ガスで満たし、最上縁をレーザー溶接で完全密閉して10年耐久を約束するアルミナセラミックの金庫です。","summary":"高純度アルミナセラミック多段キャビティと、上縁に焼成一体化されたコバール製レーザーシーム溶接フランジ。乾燥窒素（露点−60℃以下）パージ環境でALD封止窓と完全気密接合され、内周モートに乾燥剤ゲッターを収納します。","opticsAndPhysics":["樹脂モールドでは微小な水分透過を避けられないため、高密度アルミナセラミック＋コバール金属フランジのレーザーシーム溶接による「完全無機ハーメチック（気密）封止」を採用します。","キャビティ外周に設けた深溝モート空間が、FH02-14の乾燥剤ゲッターリングを光学有効エリア外へ安全格納します。","底面外周の銀はんだLGAボール群が3倍帯域電源・制御を低インダクタンス接続し、中央は銅インレイ冷却ブロックへ直接熱結合します。"],"formula":{"expression":"Leak Rate < 1 × 10^-9 atm·cm^3/s (He Fine Leak Test, MIL-STD-883)","description":"ヘリウムリーク試験基準を満たす完全無機気密封止により、10年間の内部超低湿環境を保証します。"},"nextGenInnovation":"多層ALD膜＋乾燥窒素ハーメチック容器＋内蔵ゲッターの「三重防湿アーキテクチャ」を支える気密セラミック器。","specs":[{"label":"筐体外形","value":"56.0 × 44.0 × 7.6 mm（内周ゲッターモート付）"},{"label":"気密溶接面","value":"コバール合金レーザーシーム溶接フランジ"},{"label":"封入雰囲気","value":"超高純度乾燥N₂ガス（露点 ≤ −60℃）"},{"label":"リーク基準","value":"< 10⁻⁹ atm·cm³/s（完全ハーメチック）"}],"references":["MIL-STD-883 Method 1014 Seal (Hermetic Fine/Gross Helium Leak) Test Standard","Hermetic Ceramic-Kovar Laser Seam Welding for Environmental-Sensitive Optoelectronic Sensors"],"mirai":{"fhId":"FH02","volume":1,"badge":"超知能加速","eta":"2028 Q2〜2028 Q4","score":86,"axes":[18,13,19,18,18],"scoreRationale":"ベイヤー配列撤廃＋Foveon超えの急峻な色分離という構造優位性（19点）と物理突破（18点）は圧巻。一方、透明電極ロス（光利用率200〜250%級が物理上限）、現行試作の暗電流5桁ギャップ、鉛フリー化、PVD多層微細ビアの量産難度を厳格に見積もり量産民主化13点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"白色光・実効光利用率","current2026":"約25〜28%（CFで2/3吸収廃棄）","future2028":"実証47〜53%→目標60〜75%（実効2.0〜2.8倍・+1〜1.5段）"},{"metric":"色分離・偽色・モアレ","current2026":"デモザイク補間必須・偽色/モアレ発生","future2028":"1画素で完全RGB取得・Foveon比で極めて高い色純度"},{"metric":"光電変換と回路の構造","current2026":"PDと回路が面積を奪い合う","future2028":"薄膜光電変換層とCMOS回路が完全独立積層（GS容易）"},{"metric":"暗電流・環境規制ハードル","current2026":"室温0.02〜0.05 e-/s/pix・完全無毒Si","future2028":"現行試作暗電流5桁高＆鉛使用→ASI鉛フリー・低暗電流化必須"}],"sourceUrls":[{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (1)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12176651/"},{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (2)","url":"https://ethz.ch/en/news-and-events/eth-news/news/2025/06/better-images-for-humans-and-computers.html"},{"label":"Panasonic Holdings 公式プレスリリース（2023年3月17日、単層OPF有機センサー＋カラーフィルターによる600 nm透過1%未満・120 dB同時HDR・グローバルシャッター基盤実証）","url":"https://news.panasonic.com/global/topics/13982"},{"label":"arXiv（2026年9月、\\"PeroMAS: A Multi-agent System of Perovskite Material Discovery\\" — マルチエージェントAIによるペロブスカイト材料設計の先行研究）","url":"https://arxiv.org/html/2602.13312v2"}],"beginnerTitle":"乾燥窒素を閉じ込める「完全密閉セラミック金庫」","beginnerSummary":"ペロブスカイト膜の10年寿命を守るため、センサーの中をカラカラの乾燥窒素ガスで満たし、金属のフチをレーザー溶接で完全に密閉する焼き物の器です。外側の溝には湿気吸い取りリングが収まる工夫もされています。","beginnerPoints":["プラスチック容器ではわずかに湿気が抜けてしまうため、水分を一切通さないセラミックと金属溶接の「完全気密」を採用しています。","一番上の銀色の枠（コバールフランジ）に、上のALDガラス窓をレーザーで1周ぐるっと溶接します。","底の銀色の丸い端子（LGAボール）が、3倍になった高速データ用の電源と信号を安定供給します。"],"beginnerCaution":"完全気密セラミック容器はコストが上がりますが、湿気に弱いペロブスカイトを世界中の海辺や熱帯雨林で安心して使えるカメラにするための必須投資です。","glossaryIds":["004","101"]}},{"id":"mirai-fh02-desiccant-getter-ring","diagramType":"mirai_fh02_desiccant_getter_ring","order":30,"miraiSubView":2,"swatchColor":"#10b981","groupKey":"fh02_encapsulation","assembledPos":[0,2.65,0],"explodeOffset":[-20,13,0],"edgeOpacity":0.22,"title":"FH02-14. 内周モート薄膜・水分／酸素ゲッターリング（乾燥剤）","subtitle":"In-Cavity Porous MOF / CaO Moisture & O2 Scavenger Desiccant Getter Ring","category":"FH02 3層垂直RGB / パッケージ内10年長期除湿ゲッター","plainAnalogy":"密閉容器の中に万が一残ったわずかな水分や酸素を10年間ずっと吸い取り続け、ペロブスカイトの劣化を食い止める極小ハイテク乾燥剤リングです。","summary":"気密セラミックキャリアの内周モートに8個のチタンクリップで固定された、金属有機構造体（MOF）／酸化カルシウム（CaO）系多孔質水分・酸素スカベンジャー（ゲッター）リング。PTFE透湿保護窓越しに内部微量のH₂O/O₂を化学吸着し続けます。","opticsAndPhysics":["気密溶接時に内部構造材から微量脱ガス（Outgassing）されるH₂OやO₂分子、および10年間で溶接界面から極微量拡散する水分をゼロppm近傍へ化学捕集します。","上面を微多孔ePTFE（フッ素樹脂）防塵メンブレンで覆うことで、乾燥剤の微粉が36×24 mm光学受光面へ飛散（ダスト汚染）するリスクを完全に排除します。","8か所のチタンクランプクリップにより、カメラ落下衝撃（>1,000 G）でもリングの脱落やガタつきを防止します。"],"formula":{"expression":"[H2O]_cavity < 0.1 ppm  &  [O2]_cavity < 1 ppm (10-Year Getter Capacity)","description":"内蔵MOF/CaO化学ゲッターの吸着余力により、10年運用期間を通じてキャビティ内部を超乾燥・無酸素に保ちます。"},"nextGenInnovation":"有機EL・宇宙用撮像素子の長期ゲッター技術をフルサイズカメラ内周モートへ極小統合した10年耐久保険。","specs":[{"label":"吸着材料","value":"多孔質MOF / CaO系 水分・酸素化学ゲッター"},{"label":"防塵保護膜","value":"微多孔ePTFE蒸気透過・粉塵遮断ウィンドウ ×4"},{"label":"固定機構","value":"チタン製マイクロ保持クリップ ×8（耐衝撃）"},{"label":"維持内部環境","value":"H₂O < 0.1 ppm / O₂ < 1 ppm（10年保持）"}],"references":["SAES Getters / OLED Hermetic Cavity Moisture & Oxygen Desiccant Getter Engineering Standards","ETH Zurich / Empa, Nature 642:592–598 (2025) — Perovskite Stability Against H2O/O2 Ingress"],"mirai":{"fhId":"FH02","volume":1,"badge":"超知能加速","eta":"2028 Q2〜2028 Q4","score":86,"axes":[18,13,19,18,18],"scoreRationale":"ベイヤー配列撤廃＋Foveon超えの急峻な色分離という構造優位性（19点）と物理突破（18点）は圧巻。一方、透明電極ロス（光利用率200〜250%級が物理上限）、現行試作の暗電流5桁ギャップ、鉛フリー化、PVD多層微細ビアの量産難度を厳格に見積もり量産民主化13点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"白色光・実効光利用率","current2026":"約25〜28%（CFで2/3吸収廃棄）","future2028":"実証47〜53%→目標60〜75%（実効2.0〜2.8倍・+1〜1.5段）"},{"metric":"色分離・偽色・モアレ","current2026":"デモザイク補間必須・偽色/モアレ発生","future2028":"1画素で完全RGB取得・Foveon比で極めて高い色純度"},{"metric":"光電変換と回路の構造","current2026":"PDと回路が面積を奪い合う","future2028":"薄膜光電変換層とCMOS回路が完全独立積層（GS容易）"},{"metric":"暗電流・環境規制ハードル","current2026":"室温0.02〜0.05 e-/s/pix・完全無毒Si","future2028":"現行試作暗電流5桁高＆鉛使用→ASI鉛フリー・低暗電流化必須"}],"sourceUrls":[{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (1)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12176651/"},{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (2)","url":"https://ethz.ch/en/news-and-events/eth-news/news/2025/06/better-images-for-humans-and-computers.html"},{"label":"Panasonic Holdings 公式プレスリリース（2023年3月17日、単層OPF有機センサー＋カラーフィルターによる600 nm透過1%未満・120 dB同時HDR・グローバルシャッター基盤実証）","url":"https://news.panasonic.com/global/topics/13982"},{"label":"arXiv（2026年9月、\\"PeroMAS: A Multi-agent System of Perovskite Material Discovery\\" — マルチエージェントAIによるペロブスカイト材料設計の先行研究）","url":"https://arxiv.org/html/2602.13312v2"}],"beginnerTitle":"わずかな湿気も逃さず吸う「内蔵ハイテク乾燥剤リング（ゲッター）」","beginnerSummary":"お菓子の袋に入っている乾燥剤の超ハイテク版です。気密容器のフチの溝にエメラルド色の乾燥リング（ゲッター）を仕込み、10年間にわずかに発生した水分や酸素分子を片っ端から吸い取ってペロブスカイトを守り抜きます。","beginnerPoints":["白い極薄フィルター（ePTFE）が湿気だけを通し、乾燥剤の粉がセンサーの受光面へ飛ばないようガードします。","8個の頑丈なチタン製クリップでしっかり固定されているため、カメラを持ち運ぶ振動でもズレません。","「ALDガラス窓」「窒素気密セラミック」「内蔵ゲッター」の三重プロテクトがFH02の耐久性を支えます。"],"beginnerCaution":"ペロブスカイトはわずかな水分・酸素でも分解が進むため、この見えない地味なゲッターリングの有無が製品の寿命を大きく左右します。","glossaryIds":["004","101"]}},{"id":"mirai-fh02-highspeed-fpc-array","diagramType":"mirai_fh02_highspeed_fpc_array","order":31,"miraiSubView":2,"swatchColor":"#ea580c","groupKey":"fh02_io","assembledPos":[0,-1.65,0],"explodeOffset":[0,-12,22],"edgeOpacity":0.22,"title":"FH02-15. 左右対称3倍帯域デュアルS字FPC＆32個SMD電源バンク","subtitle":"Dual Symmetric Left/Right 3×-Bandwidth S-Curved FPC Ribbons & 32-Cap SMD Bank","category":"FH02 3層垂直RGB / 3色フル解像度・左右デュアル高速伝送","plainAnalogy":"1画素から赤・緑・青すべてのフルデータ（従来の3倍！）が出てくるため、左右両側から2本の超高速リボン配線で同時に流し出す二刀流ハーネスです。","summary":"3層垂直RGBセンサー特有の3倍画素情報量（完全非補間RGB16-bit）をボトルネックゼロで伝送するため、左右対称（−X/+X）に配置されたデュアルS字ポリイミドFPCハーネスと肩部32個MLCCデカップリングバンクの複合アセンブリ。","opticsAndPhysics":["同じ3,300万画素でもベイヤー配列は1画素1色（33Mサンプル）ですが、FH02は1画素3色（99Mフルカラーサンプル）を同時に生み出すため、実効データ帯域が最大3倍へ増加します。","左右両側へ完全対称にS字FPCを2系統引き出すことで、伝送帯域を倍増させると同時に、IBIS手ブレ補正駆動時にFPCの反発バネ力が左右で相殺（ゼロ・モーメント化）され、制御精度が向上します。","両肩に並ぶ計32個の0402 MLCCが、3チャンネル同時ADC変換時の電源インピーダンスを低減します。"],"formula":{"expression":"Data_FH02 = 3 × (W × H × 16 bit × fps)  |  Torque_IBIS = F_left - F_right ≈ 0","description":"3倍のRGBフルデータ帯域を左右2系統で分担しつつ、IBIS駆動時のFPC反力トルクを対称相殺します。"},"nextGenInnovation":"3層垂直RGBの3倍データ帯域とIBIS無反力対称バランスを同時達成するデュアルS字FPCレイアウト。","specs":[{"label":"配線構成","value":"左右対称デュアルS字ポリイミドFPC（計48極金ZIF）"},{"label":"帯域設計","value":"3層完全RGB 16-bit同時伝送（従来比最大3×帯域）"},{"label":"搭載コンデンサ","value":"左右肩部 0402 MLCC ×32個（16個×2列）"},{"label":"EMI・剛性","value":"両系統銀メッシュシールド＋カーボンZIF補強板"}],"references":["Sony Semiconductor Dual-Side SLVS-EC High-Bandwidth Full-Frame Output Architecture","IPC-2223 Balanced Dual-Flex Mechanical Force Cancellation for 5-Axis IBIS Stages"],"mirai":{"fhId":"FH02","volume":1,"badge":"超知能加速","eta":"2028 Q2〜2028 Q4","score":86,"axes":[18,13,19,18,18],"scoreRationale":"ベイヤー配列撤廃＋Foveon超えの急峻な色分離という構造優位性（19点）と物理突破（18点）は圧巻。一方、透明電極ロス（光利用率200〜250%級が物理上限）、現行試作の暗電流5桁ギャップ、鉛フリー化、PVD多層微細ビアの量産難度を厳格に見積もり量産民主化13点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"白色光・実効光利用率","current2026":"約25〜28%（CFで2/3吸収廃棄）","future2028":"実証47〜53%→目標60〜75%（実効2.0〜2.8倍・+1〜1.5段）"},{"metric":"色分離・偽色・モアレ","current2026":"デモザイク補間必須・偽色/モアレ発生","future2028":"1画素で完全RGB取得・Foveon比で極めて高い色純度"},{"metric":"光電変換と回路の構造","current2026":"PDと回路が面積を奪い合う","future2028":"薄膜光電変換層とCMOS回路が完全独立積層（GS容易）"},{"metric":"暗電流・環境規制ハードル","current2026":"室温0.02〜0.05 e-/s/pix・完全無毒Si","future2028":"現行試作暗電流5桁高＆鉛使用→ASI鉛フリー・低暗電流化必須"}],"sourceUrls":[{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (1)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12176651/"},{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (2)","url":"https://ethz.ch/en/news-and-events/eth-news/news/2025/06/better-images-for-humans-and-computers.html"},{"label":"Panasonic Holdings 公式プレスリリース（2023年3月17日、単層OPF有機センサー＋カラーフィルターによる600 nm透過1%未満・120 dB同時HDR・グローバルシャッター基盤実証）","url":"https://news.panasonic.com/global/topics/13982"},{"label":"arXiv（2026年9月、\\"PeroMAS: A Multi-agent System of Perovskite Material Discovery\\" — マルチエージェントAIによるペロブスカイト材料設計の先行研究）","url":"https://arxiv.org/html/2602.13312v2"}],"beginnerTitle":"3倍の色データを両側から流し出す「左右2本の超高速リボン配線」","beginnerSummary":"1つの画素で赤・緑・青ぜんぶを測るFH02は、従来の3倍ものデータが一気に生まれます。そこで左右両側から2本のS字リボンケーブルを対称に伸ばし、データ渋滞をなくすと同時に手ブレ補正の動きも左右均等にバランスさせます。","beginnerPoints":["FH01が片側1本だったのに対し、FH02は左右に翼のように広がる2本のS字FPCが見た目でも大きな特徴です。","付け根の両肩に32個の極小コンデンサを並べ、3色同時変換の瞬間に電源が揺れないよう安定化しています。","左右対称のバネ力で引っ張り合うため、手ブレ補正ユニットがより軽く正確に動ける一石二鳥の設計です。"],"beginnerCaution":"3倍のデータ量はカメラ本体の画像処理エンジンやメモリーカード書き込み負担にも直結するため、内蔵DSPでの賢い圧縮連携が欠かせません。","glossaryIds":["003","004","111"]}},{"id":"mirai-fh02-thermal-chassis-plate","diagramType":"mirai_fh02_thermal_chassis_plate","order":32,"miraiSubView":2,"swatchColor":"#c26d38","groupKey":"fh02_thermal","assembledPos":[0,-5.75,0],"explodeOffset":[0,-29,0],"edgeOpacity":0.26,"title":"FH02-16. 純銅インレイ・マグネシウム冷却土台＆22枚マイクロフィン","subtitle":"Copper-Inlay Magnesium Thermal Chassis Baseplate, 22-Fin Rear Micro-Radiator & 6× Torx Bolts","category":"FH02 3層垂直RGB / 低温安定化・銅インレイ冷却骨格","plainAnalogy":"マグネシウムの軽い土台のど真ん中に純銅の放熱コアを埋め込み、背面の22枚の銅フィンで素早く冷やしてペロブスカイトの寿命と画質を守る冷却ベースです。","summary":"軽量高剛性マグネシウム外枠の中央へ純銅（C1100）熱拡散インレイブロックを圧入一体化し、背面（−Z側）に22枚の精密銅マイクロ冷却フィンバンク、3点ステンレス基準ボス、および6本のM1.4トルクスボルトを備えた熱管理ベースシャーシ。","opticsAndPhysics":["ペロブスカイト膜の長期結晶安定性と暗電流低減の両面において、動作ジャンクション温度を45℃未満に抑え込むことが極めて重要です（60℃超での連続稼働はイオンマイグレーション劣化を加速します）。","中央の純銅インレイ（k = 398 W/m·K）が3倍帯域ROIC＋カラーDSPの発熱を即座に吸い上げ、背面22枚のマイクロフィンアレイからカメラ筐体ヒートシンク／放熱ダクトへ高効率放散します。","外周はマグネシウム合金とすることで全面純銅比約45%の軽量化を達成し、IBIS 5軸駆動と冷却性能を両立します。"],"formula":{"expression":"T_perovskite = T_amb + P_ROIC+DSP · R_th(Cu-inlay + 22 fins) < 45℃","description":"純銅インレイ直結＋22枚マイクロフィン放熱により、ペロブスカイト膜の熱劣化・暗電流増大閾値を大きく下回る低温動作を実現します。"},"nextGenInnovation":"異種金属（Mg骨格×純銅コア×22枚マイクロフィン）複合により、ペロブスカイト低温長寿命化とIBIS軽量化を両立。","specs":[{"label":"複合骨格","value":"CNCマグネシウム外枠 ＋ 純銅（C1100）中央インレイ"},{"label":"背面放熱機構","value":"22枚 精密銅マイクロ冷却フィンバンク"},{"label":"締結・基準","value":"3点ステンレス基準ボス ＋ M1.4精密トルクスボルト ×6"},{"label":"目標動作温度","value":"ペロブスカイト膜面 ≤ 45℃（連続動画時）"}],"references":["ETH Zurich / Empa, Nature 642:592–598 (2025) — Thermal Stability & Dark-Current Scaling of Perovskite Stacks","JIS H 3100 C1100 Tough-Pitch Copper & AZ91D Magnesium Alloy Hybrid Thermal Chassis Engineering"],"mirai":{"fhId":"FH02","volume":1,"badge":"超知能加速","eta":"2028 Q2〜2028 Q4","score":86,"axes":[18,13,19,18,18],"scoreRationale":"ベイヤー配列撤廃＋Foveon超えの急峻な色分離という構造優位性（19点）と物理突破（18点）は圧巻。一方、透明電極ロス（光利用率200〜250%級が物理上限）、現行試作の暗電流5桁ギャップ、鉛フリー化、PVD多層微細ビアの量産難度を厳格に見積もり量産民主化13点・総合86点とした。","baselineMode":"sensor","comparisonRows":[{"metric":"白色光・実効光利用率","current2026":"約25〜28%（CFで2/3吸収廃棄）","future2028":"実証47〜53%→目標60〜75%（実効2.0〜2.8倍・+1〜1.5段）"},{"metric":"色分離・偽色・モアレ","current2026":"デモザイク補間必須・偽色/モアレ発生","future2028":"1画素で完全RGB取得・Foveon比で極めて高い色純度"},{"metric":"光電変換と回路の構造","current2026":"PDと回路が面積を奪い合う","future2028":"薄膜光電変換層とCMOS回路が完全独立積層（GS容易）"},{"metric":"暗電流・環境規制ハードル","current2026":"室温0.02〜0.05 e-/s/pix・完全無毒Si","future2028":"現行試作暗電流5桁高＆鉛使用→ASI鉛フリー・低暗電流化必須"}],"sourceUrls":[{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (1)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12176651/"},{"label":"ETH Zurich / Empa *Nature* 2025年6月18日原著論文（*Nature* 642:592–598、\\"Vertically stacked monolithic perovskite colour photodetectors\\" — PVD共蒸着3層RGB・EQE 47〜53%〔約2倍〕・Foveon比大幅な色分離優位） (2)","url":"https://ethz.ch/en/news-and-events/eth-news/news/2025/06/better-images-for-humans-and-computers.html"},{"label":"Panasonic Holdings 公式プレスリリース（2023年3月17日、単層OPF有機センサー＋カラーフィルターによる600 nm透過1%未満・120 dB同時HDR・グローバルシャッター基盤実証）","url":"https://news.panasonic.com/global/topics/13982"},{"label":"arXiv（2026年9月、\\"PeroMAS: A Multi-agent System of Perovskite Material Discovery\\" — マルチエージェントAIによるペロブスカイト材料設計の先行研究）","url":"https://arxiv.org/html/2602.13312v2"}],"beginnerTitle":"ペロブスカイトを冷たく長持ちさせる「純銅埋め込み＆22枚フィン土台」","beginnerSummary":"ペロブスカイト膜は高温になると暗ノイズが増え、寿命も縮んでしまいます。そこで軽いマグネシウムの土台のど真ん中に熱伝導抜群の純銅ブロックを埋め込み、後ろ側に並んだ22枚の銅フィンから素早く熱を逃がす贅沢な冷却構造を採用しました。","beginnerPoints":["3Dモデルを裏側や斜め後ろから見ると、22枚の美しい銅製マイクロ冷却フィンと中央の銅インレイがくっきり見えます。","外枠をマグネシウムにすることで、全部を銅にするよりずっと軽く仕上げ、手ブレ補正の負担も減らしています。","6本の精密トルクスボルトと3つの基準台座で全16層をピタッと固定し、2028年の3層垂直RGBモジュールが完成します。"],"beginnerCaution":"3倍のデータ量を処理するROICとカラーDSPの熱を膜へ溜めないことが、ペロブスカイトの10年寿命と暗所画質を守る最後かつ最重要の砦です。","glossaryIds":["004","008","101"]}}]'),s={unitId:e,version:r,nameJa:a,nameEn:t,declaredPartCount:32,parts:i};export{o as declaredPartCount,s as default,t as nameEn,a as nameJa,i as parts,e as unitId,r as version};
